<?php
session_start();
if (!isset($_SESSION['logged_in']) || $_SESSION['logged_in'] !== true) { header('Location: login.php'); exit; }

$display=strtolower(trim($_GET['display']??'sales'));
$salesReportView=(string)($_GET['sales_report_view']??'preauction');
if(!in_array($salesReportView,['preauction','wizara'],true))$salesReportView='preauction';
if(!in_array($display,['sales','preauction','kagera','clean','direct','totalclean','farmgate'],true))$display='sales';
/* Manual terminal market prices: persistent, report-date-specific and authenticated. */
if(!isset($_SESSION['terminal_price_csrf']))$_SESSION['terminal_price_csrf']=bin2hex(random_bytes(24));
function terminal_price_db(): PDO {
 static $pdo=null;if($pdo instanceof PDO)return $pdo;
 $url=getenv('DATABASE_URL');$parts=$url?parse_url($url):false;
 if(!$parts||empty($parts['host'])||empty($parts['user'])||empty($parts['path']))throw new RuntimeException('Database configuration is unavailable.');
 $dsn=sprintf('pgsql:host=%s;port=%d;dbname=%s',$parts['host'],(int)($parts['port']??5432),ltrim($parts['path'],'/'));
 return $pdo=new PDO($dsn,urldecode($parts['user']),urldecode($parts['pass']??''),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
}
function terminal_price_table(PDO $pdo):void{
 $pdo->exec('CREATE TABLE IF NOT EXISTS public.dashboard_terminal_prices (season VARCHAR(9) NOT NULL, report_date DATE NOT NULL, coffee_type VARCHAR(8) NOT NULL CHECK (coffee_type IN (\'arabica\',\'robusta\')), price_usd_kg NUMERIC(12,4) NOT NULL CHECK (price_usd_kg >= 0), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (season, report_date, coffee_type))');
}
if(($_GET['action']??'')==='save_terminal_price'){
 header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
 try{
  if(($_SERVER['REQUEST_METHOD']??'')!=='POST')throw new InvalidArgumentException('POST is required.');
  if(!hash_equals($_SESSION['terminal_price_csrf'],(string)($_POST['csrf']??'')))throw new InvalidArgumentException('Invalid security token. Refresh and try again.');
  $season=(string)($_POST['season']??'');$date=(string)($_POST['report_date']??'');$type=(string)($_POST['coffee_type']??'');$raw=trim((string)($_POST['price']??''));
  if(!preg_match('/^(\d{4})\/(\d{4})$/',$season,$m)||(int)$m[2]!==((int)$m[1]+1))throw new InvalidArgumentException('Invalid season.');
  $dt=DateTimeImmutable::createFromFormat('!Y-m-d',$date);
  if(!$dt||$dt->format('Y-m-d')!==$date||$dt->format('N')!=='5'||$date<$m[1].'-07-01'||$date>$m[2].'-06-30')throw new InvalidArgumentException('Invalid Friday report date.');
  if(!in_array($type,['arabica','robusta'],true))throw new InvalidArgumentException('Invalid coffee type.');
  if(!preg_match('/^\d{1,8}(?:\.\d{1,4})?$/D',$raw)||(float)$raw>99999999)throw new InvalidArgumentException('Enter a valid non-negative USD/kg price (up to 4 decimal places).');
  $pdo=terminal_price_db();terminal_price_table($pdo);
  $q=$pdo->prepare('INSERT INTO public.dashboard_terminal_prices (season,report_date,coffee_type,price_usd_kg) VALUES (:season,:date,:type,:price) ON CONFLICT (season,report_date,coffee_type) DO UPDATE SET price_usd_kg=EXCLUDED.price_usd_kg,updated_at=NOW()');
  $q->execute(['season'=>$season,'date'=>$date,'type'=>$type,'price'=>$raw]);
  echo json_encode(['success'=>true,'price'=>number_format((float)$raw,4,'.','')]);
 }catch(InvalidArgumentException $e){http_response_code(422);echo json_encode(['success'=>false,'message'=>$e->getMessage()]);}
 catch(Throwable $e){error_log('Terminal price save: '.$e->getMessage());http_response_code(500);echo json_encode(['success'=>false,'message'=>'Unable to save the price. Please try again.']);}
 exit;
}
/* Official TCB market reference prices. Cache the complete validated publication. */
function tcb_market_prices(): array {
  // Screenshot-verified TCB publication of 23 Oct 2026. Used only when no valid
  // newer publication can be fetched; never describe these figures as live.
  $baseline=['ny'=>6.9,'london'=>3.3,'hard_cherry'=>4500,'cpu'=>12000,
    'hp'=>10500,'robusta_cherry'=>3800,'auction_arabica'=>7.0,'auction_robusta'=>3.4];
  $fallback=['prices'=>$baseline,'published'=>'2026-10-23','status'=>'reference','fetched_at'=>0];
  $cache=sys_get_temp_dir().'/tcb_average_market_prices_v2.json';
  $old=null;
  if(is_file($cache)){
    $decoded=json_decode((string)@file_get_contents($cache),true);
    if(is_array($decoded)&&isset($decoded['prices'])&&is_array($decoded['prices'])
       && count(array_intersect_key($decoded['prices'],$baseline))===8
       && !empty($decoded['published']))$old=$decoded;
  }
  if($old && time()-(int)($old['fetched_at']??0)<21600)return $old;
  $previous=$old ?: $fallback;
  if(!function_exists('curl_init') || !class_exists('DOMDocument')){
    error_log('TCB market prices: PHP cURL or DOM extension missing');
    return array_merge($previous,['status'=>$old?'cached':'reference']);
  }
  $ch=curl_init('https://www.coffee.go.tz/pages/average-market-price');
  curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,
    CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>20,CURLOPT_SSL_VERIFYPEER=>true,
    CURLOPT_USERAGENT=>'Mozilla/5.0 (compatible; TCB-SalesDashboard/1.0)',CURLOPT_MAXREDIRS=>3]);
  $html=curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);
  $err=curl_error($ch);curl_close($ch);
  if(!is_string($html)||$http!==200||strlen($html)>3000000){
    error_log('TCB market prices: HTTP '.$http.' '.$err);
    return array_merge($previous,['status'=>$old?'cached':'reference']);
  }
  $dom=new DOMDocument();$prev=libxml_use_internal_errors(true);
  $loaded=$dom->loadHTML('<?xml encoding="utf-8"?>'.$html);
  libxml_clear_errors();libxml_use_internal_errors($prev);
  if(!$loaded)return array_merge($previous,['status'=>$old?'cached':'reference']);
  $xp=new DOMXPath($dom);$pairs=[];
  // The public page contains separate Terminal, Farm Gate and Auction sections.
  // Extract the label/value from each row, irrespective of th/td markup.
  foreach($xp->query('//tr') as $tr){
    $cells=[];
    foreach($tr->childNodes as $node){
      if($node instanceof DOMElement && in_array(strtolower($node->tagName),['td','th'],true)){
        $v=trim(preg_replace('/\s+/u',' ',str_replace("\xc2\xa0",' ',$node->textContent)));
        if($v!=='')$cells[]=$v;
      }
    }
    if(count($cells)<2)continue;
    for($i=0;$i<count($cells)-1;$i++){
      if(preg_match('/^\s*([\d,]+(?:\.\d+)?)\s*$/',$cells[$i+1],$m))
        $pairs[]=[$cells[$i],(float)str_replace(',','',$m[1])];
    }
  }
  // Also handle CMS pages that render label/value pairs using divs instead of rows.
  if(count($pairs)<8){
    $plain=trim(preg_replace('/\s+/u',' ',$dom->textContent));
    $labels=['NYC','London','H/Arabica (Maganda)','Arabica (CPU)','Arabica HP',
      'Robusta (Maganda)','Arabica-Clean Coffee','Robusta- Clean Coffee'];
    foreach($labels as $label){
      $quoted=preg_quote($label,'/');
      if(preg_match('/'.$quoted.'\s*([\d,]+(?:\.\d+)?)/iu',$plain,$m))
        $pairs[]=[$label,(float)str_replace(',','',$m[1])];
    }
  }
  $patterns=[
    'ny'=>'/^(?:NYC|NY|New York)$/i',
    'london'=>'/^London$/i',
    'hard_cherry'=>'/^H\s*\/\s*Arabica\s*\((?:Maganda|Dry Cherry)\)$/i',
    'cpu'=>'/^Arabica\s*\(?CPU\)?$/i',
    'hp'=>'/^Arabica\s*HP$/i',
    'robusta_cherry'=>'/^Robusta\s*\((?:Maganda|Dry Cherry)\)$/i',
    'auction_arabica'=>'/^Arabica\s*[-–]?\s*Clean\s+Coffee$/i',
    'auction_robusta'=>'/^Robusta\s*[-–]?\s*Clean\s+Coffee$/i'];
  $prices=[];
  foreach($patterns as $key=>$regex){
    foreach($pairs as [$label,$value]){
      if(preg_match($regex,trim($label)) && $value>0){$prices[$key]=$value;break;}
    }
  }
  if(count($prices)!==8){
    error_log('TCB market prices: parsing failed; found '.implode(',',array_keys($prices)));
    return array_merge($previous,['status'=>$old?'cached':'reference']);
  }
  $pageText=trim(preg_replace('/\s+/u',' ',$dom->textContent));$published=null;
  if(preg_match('/\b(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*,?\s+(20\d{2})\b/i',$pageText,$m)){
    $dt=DateTimeImmutable::createFromFormat('!j M Y',$m[1].' '.ucfirst(strtolower($m[2])).' '.$m[3]);
    if($dt)$published=$dt->format('Y-m-d');
  }
  if(!$published){error_log('TCB market prices: publication date missing');return array_merge($previous,['status'=>$old?'cached':'reference']);}
  // Never replace a newer verified publication with an older one.
  if($published < $previous['published'])return array_merge($previous,['status'=>$old?'cached':'reference']);
  $data=['prices'=>$prices,'published'=>$published,'status'=>'live','fetched_at'=>time()];
  @file_put_contents($cache,json_encode($data),LOCK_EX);
  return $data;
}

/* Friday-specific market snapshots. Manual overrides are never overwritten by website refreshes. */
function dashboard_market_keys():array{return ['ny','london','hard_cherry','robusta_cherry','cpu','hp','auction_arabica','auction_robusta'];}
function dashboard_market_table(PDO $db):void{
 $db->exec("CREATE TABLE IF NOT EXISTS public.dashboard_market_friday_prices (season VARCHAR(9) NOT NULL,report_date DATE NOT NULL,price_key VARCHAR(32) NOT NULL,price NUMERIC(14,4) NOT NULL CHECK(price>=0),source VARCHAR(12) NOT NULL CHECK(source IN ('manual','website')),published DATE,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(season,report_date,price_key))");
}
if(($_GET['action']??'')==='save_market_friday_price'){
 header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
 try{
  if(($_SERVER['REQUEST_METHOD']??'')!=='POST')throw new InvalidArgumentException('POST required.');
  if(!hash_equals($_SESSION['terminal_price_csrf'],(string)($_POST['csrf']??'')))throw new InvalidArgumentException('Security token expired. Reload the dashboard.');
  $ss=(string)($_POST['season']??'');$dd=(string)($_POST['report_date']??'');$key=(string)($_POST['price_key']??'');$raw=trim((string)($_POST['price']??''));
  if(!preg_match('/^(\d{4})\/(\d{4})$/',$ss,$m)||(int)$m[2]!==((int)$m[1]+1))throw new InvalidArgumentException('Invalid season.');
  $date=DateTimeImmutable::createFromFormat('!Y-m-d',$dd);
  if(!$date||$date->format('Y-m-d')!==$dd||$date->format('N')!=='5'||$dd<$m[1].'-07-01'||$dd>$m[2].'-06-30')throw new InvalidArgumentException('Invalid reporting Friday.');
  if(!in_array($key,dashboard_market_keys(),true))throw new InvalidArgumentException('Invalid price category.');
  if(!preg_match('/^\d{1,10}(?:\.\d{1,4})?$/D',$raw))throw new InvalidArgumentException('Enter a non-negative price with up to four decimal places.');
  $db=terminal_price_db();dashboard_market_table($db);
  $q=$db->prepare("INSERT INTO public.dashboard_market_friday_prices(season,report_date,price_key,price,source,published) VALUES (:s,:d,:k,:p,'manual',NULL) ON CONFLICT(season,report_date,price_key) DO UPDATE SET price=EXCLUDED.price,source='manual',published=NULL,updated_at=NOW()");
  $q->execute(['s'=>$ss,'d'=>$dd,'k'=>$key,'p'=>$raw]);
  echo json_encode(['success'=>true,'price'=>(float)$raw,'price_key'=>$key]);
 }catch(InvalidArgumentException $e){http_response_code(422);echo json_encode(['success'=>false,'message'=>$e->getMessage()]);}
 catch(Throwable $e){error_log('Market price manual save: '.$e->getMessage());http_response_code(500);echo json_encode(['success'=>false,'message'=>'Database save failed. Please try again.']);}
 exit;
}
function dashboard_friday_market_prices(string $season,string $friday,array $market):array{
 $latest=$market['prices']??[];
 try{
  $db=terminal_price_db();dashboard_market_table($db);
  // Save website prices only for their own publication Friday; never assign a later publication to an earlier Friday.
  $published=(string)($market['published']??'');$dt=DateTimeImmutable::createFromFormat('!Y-m-d',$published);
  if($dt&&$dt->format('Y-m-d')===$published&&$dt->format('N')==='5'&&$published===$friday&&($market['status']??'')==='live'){
   $q=$db->prepare("INSERT INTO public.dashboard_market_friday_prices(season,report_date,price_key,price,source,published) VALUES (:s,:d,:k,:p,'website',:pub) ON CONFLICT(season,report_date,price_key) DO NOTHING");
   foreach(dashboard_market_keys() as $key)if(isset($latest[$key])&&is_numeric($latest[$key]))$q->execute(['s'=>$season,'d'=>$friday,'k'=>$key,'p'=>$latest[$key],'pub'=>$published]);
  }
  $q=$db->prepare('SELECT price_key,price FROM public.dashboard_market_friday_prices WHERE season=:s AND report_date=:d');$q->execute(['s'=>$season,'d'=>$friday]);
  foreach($q as $r)if(in_array($r['price_key'],dashboard_market_keys(),true))$latest[$r['price_key']]=(float)$r['price'];
 }catch(Throwable $e){error_log('Market Friday prices: '.$e->getMessage());}
 return $latest;
}

/* Certified Coffee: manual farmgate figures, independent for each Friday report. */
function certified_coffee_table(PDO $pdo):void{
 $pdo->exec("CREATE TABLE IF NOT EXISTS public.dashboard_certified_coffee (season VARCHAR(9) NOT NULL, report_date DATE NOT NULL, week_mt NUMERIC(18,3) NOT NULL DEFAULT 0 CHECK(week_mt>=0), week_value_tzs NUMERIC(22,2) NOT NULL DEFAULT 0 CHECK(week_value_tzs>=0), season_mt NUMERIC(18,3) NOT NULL DEFAULT 0 CHECK(season_mt>=0), season_value_tzs NUMERIC(22,2) NOT NULL DEFAULT 0 CHECK(season_value_tzs>=0), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(season,report_date))");
}
if(($_GET['action']??'')==='save_certified_coffee'){
 header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
 try{
  if(($_SERVER['REQUEST_METHOD']??'')!=='POST')throw new InvalidArgumentException('POST is required.');
  if(!hash_equals($_SESSION['terminal_price_csrf'],(string)($_POST['csrf']??'')))throw new InvalidArgumentException('Security token expired. Refresh and retry.');
  $ss=(string)($_POST['season']??'');$dd=(string)($_POST['report_date']??'');
  if(!preg_match('/^(\d{4})\/(\d{4})$/',$ss,$mm)||(int)$mm[2]!==((int)$mm[1]+1))throw new InvalidArgumentException('Invalid season.');
  $dt=DateTimeImmutable::createFromFormat('!Y-m-d',$dd);
  if(!$dt||$dt->format('Y-m-d')!==$dd||$dt->format('N')!=='5'||$dd<$mm[1].'-07-01'||$dd>$mm[2].'-06-30')throw new InvalidArgumentException('Invalid Friday report date.');
  $values=[];
  foreach(['week_mt'=>3,'week_value_tzs'=>2,'season_mt'=>3,'season_value_tzs'=>2] as$key=>$dec){
   $raw=trim((string)($_POST[$key]??''));
   if(!preg_match('/^\d{1,14}(?:\.\d{1,'.$dec.'})?$/D',$raw))throw new InvalidArgumentException('Invalid '.$key.'; use non-negative numbers with at most '.$dec.' decimal places.');
   $values[$key]=$raw;
  }
  $pdo=terminal_price_db();certified_coffee_table($pdo);
  $q=$pdo->prepare('INSERT INTO public.dashboard_certified_coffee (season,report_date,week_mt,week_value_tzs,season_mt,season_value_tzs) VALUES (:season,:report_date,:week_mt,:week_value_tzs,:season_mt,:season_value_tzs) ON CONFLICT(season,report_date) DO UPDATE SET week_mt=EXCLUDED.week_mt,week_value_tzs=EXCLUDED.week_value_tzs,season_mt=EXCLUDED.season_mt,season_value_tzs=EXCLUDED.season_value_tzs,updated_at=NOW()');
  $q->execute(['season'=>$ss,'report_date'=>$dd]+$values);
  echo json_encode(['success'=>true,'values'=>$values]);
 }catch(InvalidArgumentException $e){http_response_code(422);echo json_encode(['success'=>false,'message'=>$e->getMessage()]);}
 catch(Throwable $e){error_log('Certified Coffee save: '.$e->getMessage());http_response_code(500);echo json_encode(['success'=>false,'message'=>'Unable to save Certified Coffee figures.']);}
 exit;
}
