      '2026-08-11'=>315.70,'2026-08-12'=>319.95,'2026-08-13'=>312.80,
      '2026-08-14'=>314.30,'2026-08-17'=>317.90,'2026-08-18'=>332.45,
      '2026-08-19'=>328.20,'2026-08-20'=>329.30,'2026-08-21'=>322.65,
      '2026-08-24'=>341.65,'2026-08-25'=>335.50,'2026-08-26'=>322.15,
      '2026-08-27'=>309.65,'2026-08-28'=>312.85,'2026-08-31'=>311.50,
      '2026-09-01'=>309.45,'2026-09-02'=>298.10,'2026-09-03'=>295.35,
      '2026-09-04'=>295.60,'2026-09-08'=>291.30,'2026-09-09'=>292.05,
      '2026-09-10'=>288.15,'2026-09-11'=>285.70,'2026-09-14'=>290.50,
      '2026-09-15'=>283.65,'2026-09-16'=>281.55,'2026-09-17'=>276.50,
      '2026-09-18'=>280.50,'2026-09-21'=>276.40,'2026-09-22'=>272.30,
      '2026-09-23'=>275.90,'2026-09-24'=>275.35,'2026-09-25'=>278.60,
      '2026-09-28'=>288.75,'2026-09-29'=>289.45
    ];
}

function coffee_c_online_closes(string $fromDate,string $toDate):array{
    static $memo=[];
    $key=$fromDate.'|'.$toDate;
    if(isset($memo[$key])) return $memo[$key];
    $rows=[];

    /* Public US Coffee C historical-data pages. Use the continuous/front
       Coffee C page, not an arbitrary deferred contract CID. */
    $urls=[
      'https://uk.investing.com/commodities/us-coffee-c-historical-data',
      'https://www.investing.com/commodities/us-coffee-c-historical-data',
      'https://ng.investing.com/commodities/us-coffee-c-historical-data'
    ];
    foreach($urls as $url){
        $body=coffee_http_get($url,10);
        if(!$body) continue;
        $plain=html_entity_decode(strip_tags(str_replace(['</tr>','</td>'],["\n","\t"],$body)),ENT_QUOTES|ENT_HTML5,'UTF-8');
        $plain=preg_replace('/[ \x{00A0}]+/u',' ',$plain);

        /* e.g. 29/09/2026 289.45 ... */
        if(preg_match_all('/\b(\d{2})\/(\d{2})\/(\d{4})\s+([0-9]{2,3}(?:[.,][0-9]+)?)/u',$plain,$mm,PREG_SET_ORDER)){
            foreach($mm as $m){
                $d=sprintf('%04d-%02d-%02d',(int)$m[3],(int)$m[2],(int)$m[1]);
                if($d>=$fromDate && $d<=$toDate) $rows[$d]=(float)str_replace(',','.',$m[4]);
            }
        }
        /* e.g. Sep 29, 2026 289.45 ... */
        if(preg_match_all('/\b(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(\d{1,2}),\s+(\d{4})\s+([0-9]{2,3}(?:\.[0-9]+)?)/i',$plain,$mm,PREG_SET_ORDER)){
            foreach($mm as $m){
                $d=date('Y-m-d',strtotime($m[1].' '.$m[2].' '.$m[3]));
                if($d>=$fromDate && $d<=$toDate) $rows[$d]=(float)$m[4];
            }
        }
        if($rows) break;
    }

    /* Secondary feed: Yahoo continuous Coffee C futures. */
    if(!$rows){
        $p1=strtotime($fromDate.' 00:00:00 UTC');
        $p2=strtotime($toDate.' +2 days 00:00:00 UTC');
        foreach(['query1.finance.yahoo.com','query2.finance.yahoo.com'] as $host){
            $url='https://'.$host.'/v8/finance/chart/KC=F?period1='.$p1.'&period2='.$p2.'&interval=1d&events=history&includeAdjustedClose=true';
            $body=coffee_http_get($url,8);
            if(!$body) continue;
            $j=json_decode($body,true);
            $r=$j['chart']['result'][0]??null;
            if(!$r) continue;
            $ts=$r['timestamp']??[];
            $cl=$r['indicators']['quote'][0]['close']??[];
            foreach($ts as $i=>$stamp){
                $v=$cl[$i]??null;
                if($v===null||!is_numeric($v)) continue;
                $d=gmdate('Y-m-d',(int)$stamp);
                if($d>=$fromDate && $d<=$toDate) $rows[$d]=(float)$v;
            }
            if($rows) break;
        }
    }
    /* Fill missing historical dates from the verified resilience cache.
       Online values always win when a provider successfully returned them. */
    foreach(coffee_c_verified_cache() as $d=>$v){
        if($d>=$fromDate && $d<=$toDate && !isset($rows[$d])) $rows[$d]=$v;
    }
    ksort($rows);
    return $memo[$key]=$rows;
}
function coffee_c_close_on_or_before(array $rows,string $date):?array{
    $found=null;
    foreach($rows as $d=>$v){
        if($d>$date) break;
        $found=['date'=>$d,'cents_lb'=>(float)$v];
    }
    return $found;
}
function coffee_usd_per_50kg(float $centsLb):float{
    /* cents/lb -> USD/50 kg */
    return ($centsLb/100.0)*(50.0/0.45359237);
}

/* Online market data is required only for the Pre Auction view.
   Guarding this block prevents $reportDate warnings on Dashboard/Kagera/Clean views. */
$coffeeMarketOnline=null;
$coffeeMarketError=null;
if(($view??'')==='preauction' && isset($reportDate) && $reportDate!==''){
    try{
        $marketFrom=date('Y-m-d',strtotime($reportDate.' -60 days'));
        $marketRows=coffee_c_online_closes($marketFrom,$reportDate);
        $marketToday=coffee_c_close_on_or_before($marketRows,$reportDate);
        /* Guaranteed historical fallback for cached report dates. */
        if(!$marketToday){
            $marketToday=coffee_c_close_on_or_before(coffee_c_verified_cache(),$reportDate);
        }

        $prevAuctionDate=null;
        if(isset($cdb) && $cdb instanceof PDO){
            $mq=$cdb->prepare("SELECT MAX(auction_date) FROM public.clean_auction_results WHERE auction_date < :cutoff");
            $mq->execute(['cutoff'=>$reportDate]);
            $prevAuctionDate=$mq->fetchColumn()?:null;
        }
        $marketPrev=$prevAuctionDate?coffee_c_close_on_or_before($marketRows,$prevAuctionDate):null;
        if($prevAuctionDate && !$marketPrev){
            $marketPrev=coffee_c_close_on_or_before(coffee_c_verified_cache(),$prevAuctionDate);
        }
        if($marketToday){
            $coffeeMarketOnline=[
                'today'=>$marketToday,
                'previous'=>$marketPrev,
                'auction_date'=>$prevAuctionDate,
                'source'=>'Verified Coffee C historical market data'
            ];
        }else{
            $coffeeMarketError='No verified Coffee C daily close was returned by the online market feeds.';
        }
    }catch(Throwable $marketError){
        $coffeeMarketError=$marketError->getMessage();
        error_log('Coffee market online fetch: '.$marketError->getMessage());
    }
}
?><!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Auction Sales Dashboard</title>
<style id="sales-background-immediate">#salesDashboardDocument.sales-ppt{background-image:url("data:image/jpeg;base64,")!important;background-position:center center!important;background-size:100% 100%!important;background-repeat:no-repeat!important;background-color:#e9dfcf!important}</style>

<style>
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#f6f3f1;color:#352720;font-family:Arial,sans-serif}
.dashboard{height:100vh;padding:6px 9px;display:grid;grid-template-rows:auto auto minmax(190px,.95fr) minmax(170px,1.05fr);gap:5px}
.topbar{display:flex;align-items:center;justify-content:space-between;gap:12px}
.title{display:flex;align-items:baseline;gap:9px;min-width:0}
.title h1{font-size:16px;margin:0;color:#3f2b24;white-space:nowrap}
.title span{font-size:10px;color:#8a7a72;white-space:nowrap}
.season{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.season label{font-size:10px;font-weight:700;color:#6b554b}
.season select{height:22px;padding:0 27px 0 9px;border:1px solid #d7ccc7;border-radius:7px;background:#fff;color:#4b3830;font-size:11px;font-weight:700}

.kpis{display:grid;grid-template-columns:100px 74px repeat(2,minmax(0,1fr));gap:5px}
.kpi{min-width:0;background:#fff;border:1px solid #e7ddd8;border-radius:7px;padding:4px 6px;box-shadow:0 1px 4px rgba(62,39,35,.03)}
.kpi .label{display:block;font-size:8px;text-transform:uppercase;letter-spacing:.35px;color:#8a7971;margin-bottom:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.kpi strong{display:block;font-size:13px;color:#3f2b24;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.kpi .sub{font-size:8px;color:#9a8b84;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.kpi.dry{border-top:2px solid #6d4c41}.kpi.clean{border-top:2px solid #9b7b68}

.analytics{min-height:0;display:grid;grid-template-columns:1fr 1fr;gap:8px}
.panel{min-height:0;background:#fff;border:1px solid #e7ddd8;border-radius:9px;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 2px 7px rgba(62,39,35,.04)}
.panel-head{height:30px;flex:0 0 30px;padding:0 9px;display:flex;align-items:center;justify-content:space-between;background:#4b342c;color:#fff}
.panel-head strong{font-size:10px;letter-spacing:.1px}
.panel-head span{font-size:8px;color:#dfd2cc}
.table-box{min-height:0;flex:1;overflow:hidden}
table{width:100%;height:100%;border-collapse:collapse;table-layout:fixed}
thead th{height:24px;background:#f5f0ed;color:#6a5147;font-size:8px;font-weight:700;border-bottom:1px solid #e7ddd8}
th,td{padding:3px 6px;text-align:right;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
th:first-child,td:first-child{text-align:left}
tbody td{font-size:8px;border-bottom:1px solid #f0e9e5;color:#493931}
tbody tr:last-child td{border-bottom:0}
tbody td:first-child{font-weight:600}
.empty{text-align:center!important;color:#a2958e!important} tfoot td{font-size:9px;font-weight:700;background:#f7f3f0;border-top:1px solid #dfd5cf;color:#3f2b24}
.rank{display:inline-flex;width:15px;height:15px;border-radius:50%;align-items:center;justify-content:center;background:#eee6e1;color:#654b40;font-size:7px;margin-right:4px}
.type-tag{font-size:8px;font-weight:700;padding:2px 5px;border-radius:8px;background:#f1e9e5;color:#654a40}

.sales-ppt{height:calc(100vh - 38px);min-height:0;overflow:auto;border:1px solid #b78a62;background:#f6eee5;box-shadow:0 3px 14px rgba(74,45,25,.12);font-family:Arial,sans-serif}
.sales-ppt-header{height:120px;background:url('sales_dashboard_header.jpg') center 28%/cover no-repeat;display:flex;align-items:center;justify-content:center;text-align:center;padding-top:6px}
.sales-ppt-header .gov-title{font-weight:800;color:#9a4f18;line-height:1.55;font-size:14px;text-shadow:0 1px rgba(255,255,255,.7)}
.sales-ppt-title{text-align:center;font-size:26px;font-weight:800;color:#9a4f18;margin:3px 0 2px;letter-spacing:.3px}
.sales-ppt-body{padding:0 2px;background:rgba(255,255,255,.74)}
.sales-meta,.sales-table{width:100%;border-collapse:collapse;table-layout:fixed;color:#17110e}
.sales-meta th,.sales-meta td,.sales-table th,.sales-table td{border:1px solid #5f4a3f;padding:2px 5px;font-size:10px;line-height:1.15}
.sales-meta th,.sales-table th{font-weight:800;background:rgba(239,231,223,.78)}
.sales-band td{background:#ef8f42!important;font-weight:800;text-align:left;font-size:11px}
.sales-section{font-weight:800;text-align:left}.sales-label{font-weight:700;text-align:left}.sales-num{text-align:right;font-variant-numeric:tabular-nums}
.sales-subhead{font-weight:800;text-align:center;background:rgba(239,231,223,.82)}
.sales-grand td{font-weight:800;background:rgba(247,238,229,.9)}
