/* Pre-Auction report tables: complete outer frame + content-aware sizing */
.pre-report .pre-scroll{width:100%;overflow-x:auto;overflow-y:visible;padding:0 0 1px;margin:0 0 10px}
.pre-report .pre-scroll>table,
.pre-report table.pre-table,
.pre-report table.pre-farm-table{
  width:100%;
  border-collapse:collapse !important;
  border-spacing:0 !important;
  table-layout:auto;
  border:1px solid #555 !important;
  border-bottom:1px solid #555 !important;
  box-sizing:border-box;
}
.pre-report .pre-scroll>table th,
.pre-report .pre-scroll>table td,
.pre-report table.pre-table th,
.pre-report table.pre-table td,
.pre-report table.pre-farm-table th,
.pre-report table.pre-farm-table td{
  border:1px solid #555 !important;
  padding:4px 6px;
  height:auto;
  line-height:1.2;
  vertical-align:middle;
}
.pre-report .pre-scroll>table tr:last-child>td,
.pre-report .pre-scroll>table tr:last-child>th,
.pre-report table.pre-table tr:last-child>td,
.pre-report table.pre-table tr:last-child>th,
.pre-report table.pre-farm-table tr:last-child>td,
.pre-report table.pre-farm-table tr:last-child>th{
  border-bottom:1px solid #555 !important;
}
.pre-report .pre-scroll>table tr>*:first-child,
.pre-report table.pre-table tr>*:first-child,
.pre-report table.pre-farm-table tr>*:first-child{border-left:1px solid #555 !important}
.pre-report .pre-scroll>table tr>*:last-child,
.pre-report table.pre-table tr>*:last-child,
.pre-report table.pre-farm-table tr>*:last-child{border-right:1px solid #555 !important}
@media(max-width:700px){
 .pre-report .pre-scroll>table{min-width:max-content}
 .pre-report .pre-scroll>table th,.pre-report .pre-scroll>table td{white-space:nowrap;padding:3px 5px}
}

/* Pre-Auction report: uniform complete table grid.
   Outer borders intentionally use the SAME 1px weight as internal borders. */
.pre-report table{
  width:100%;
  border-collapse:collapse !important;
  border-spacing:0 !important;
  table-layout:auto;
  border:1px solid #555 !important;
  border-top:1px solid #555 !important;
  border-right:1px solid #555 !important;
  border-bottom:1px solid #555 !important;
  border-left:1px solid #555 !important;
  box-sizing:border-box;
}
.pre-report table thead,
.pre-report table tbody,
.pre-report table tfoot{border:0 !important}
.pre-report table tr{border:0 !important}
.pre-report table th,
.pre-report table td{
  border:1px solid #555 !important;
  padding:4px 6px;
  line-height:1.2;
  vertical-align:middle;
  box-sizing:border-box;
}
.pre-report table tr:first-child > th,
.pre-report table tr:first-child > td{border-top:1px solid #555 !important}
.pre-report table tr:last-child > th,
.pre-report table tr:last-child > td{border-bottom:1px solid #555 !important}
.pre-report table tr > *:first-child{border-left:1px solid #555 !important}
.pre-report table tr > *:last-child{border-right:1px solid #555 !important}
.pre-report .pre-scroll{
  width:100%;
  overflow-x:auto;
  overflow-y:visible;
  padding:0 0 2px;
  margin:0 0 10px;
}
@media(max-width:700px){
  .pre-report .pre-scroll{overflow-x:auto;-webkit-overflow-scrolling:touch}
  .pre-report table{min-width:max-content}
  .pre-report table th,.pre-report table td{white-space:nowrap;padding:3px 5px}
}

/* High-quality PDF capture: preserve solid text/borders and avoid faded rendering */
.pre-paper.pdf-exporting,
.pre-paper.pdf-exporting *{
  opacity:1 !important;
  filter:none !important;
  text-shadow:none !important;
  -webkit-font-smoothing:antialiased;
}
.pre-paper.pdf-exporting table,
.pre-paper.pdf-exporting th,
.pre-paper.pdf-exporting td{
  border-color:#333 !important;
}
.pre-paper.pdf-exporting{background:#fff !important;color:#111 !important}

/* Pre-Auction semantic table alignment — identical on screen and in exports */
.pre-report table th,
.pre-report table td.pre-header-cell{
  text-align:center !important;
  vertical-align:middle !important;
}
.pre-report table td.pre-number-cell{
  text-align:center !important;
  vertical-align:middle !important;
  white-space:nowrap;
}
.pre-report table td.pre-text-cell{
  text-align:left !important;
  vertical-align:middle !important;
}
/* Percentage headers already declare the unit; values therefore display as plain numbers. */
.tc-summary-actions{display:flex;align-items:center;gap:7px;margin-left:auto;font-size:11px;font-weight:600}.tc-summary-actions select{min-width:125px;height:30px;border:1px solid #d8cec7;border-radius:6px;background:#fff;color:#4b342c;padding:0 7px}.totalclean-grade-table{width:100%;border-collapse:collapse;font-size:11px}.totalclean-grade-table th,.totalclean-grade-table td{padding:8px 12px;border-bottom:1px solid #e9e0db;text-align:right}.totalclean-grade-table th:first-child,.totalclean-grade-table td:first-child{text-align:left}.totalclean-grade-table .tc-grade-family{background:#efe9e3;font-weight:800}.totalclean-grade-table tfoot{background:#f5f0eb;font-weight:800}.totalclean-grade-table{table-layout:auto!important;min-width:0!important;width:100%!important;font-size:12px!important}.totalclean-grade-table th,.totalclean-grade-table td{padding:5px 7px!important;white-space:normal!important;line-height:1.3}.totalclean-grade-table th:first-child,.totalclean-grade-table td:first-child{width:32%;min-width:155px;overflow-wrap:anywhere}.totalclean-grade-table th:not(:first-child),.totalclean-grade-table td:not(:first-child){width:17%;white-space:nowrap!important;font-variant-numeric:tabular-nums}@media(max-width:680px){.totalclean-grade-table{font-size:10px!important}.totalclean-grade-table th,.totalclean-grade-table td{padding:4px!important}}.totalclean-grade-table[hidden],.totalclean-table[hidden]{display:none!important} .tc-grade-analysis[hidden]{display:none!important}.tc-grade-analysis{padding:14px 16px;border-top:1px solid #e5dad3;background:#fff}.tc-grade-analysis-heading{display:flex;flex-wrap:wrap;gap:6px 14px;align-items:baseline;margin-bottom:10px}.tc-grade-analysis-heading strong{font-size:14px;color:#49352e}.tc-grade-analysis-heading span{font-size:11px;color:#79675e}.tc-grade-analysis-scroll{overflow-x:auto}.tc-grade-analysis-table{width:100%;border-collapse:collapse;font-size:11px;min-width:790px}.tc-grade-analysis-table th,.tc-grade-analysis-table td{padding:7px 8px;border-bottom:1px solid #e9e1dc;text-align:right;white-space:nowrap}.tc-grade-analysis-table th{background:#503a31;color:#fff}.tc-grade-analysis-table th:first-child,.tc-grade-analysis-table td:first-child{text-align:left}.tc-grade-analysis-table tbody tr:nth-child(even){background:#faf7f5}.tc-grade-analysis-notes{font-size:12px;line-height:1.5;color:#51433d;margin-top:10px}.tc-grade-analysis-notes p{margin:5px 0}.tc-grade-method{color:#76675f;font-size:11px}@media(max-width:650px){.tc-summary-actions{margin-left:0}.tc-summary-actions select{min-width:105px}}
</style>
<style id="report-sticky-controls">
/* Sticky report controls: the document scrolls underneath while controls stay available.
   The export bars are outside the printable paper, so sticky positioning cannot be
   suppressed by the paper's overflow clipping. */
html:has(body.report-sticky-mode),body.report-sticky-mode{
 height:auto!important;min-height:100%!important;overflow-x:hidden!important;overflow-y:auto!important;
}
body.report-sticky-mode .dashboard{
 display:flex!important;flex-direction:column!important;align-items:stretch!important;
 height:auto!important;min-height:100dvh!important;overflow:visible!important;padding-top:var(--report-fixed-controls-height,105px)!important;
 grid-template-rows:none!important;gap:0!important;
}
body.report-sticky-mode .dashboard>.topbar{
 position:fixed!important;top:0!important;left:0!important;right:0!important;width:100%!important;z-index:1000!important;
 flex:0 0 auto!important;background:#f6f3f1!important;
 padding:9px 10px!important;border-bottom:1px solid #d9c9bd!important;
 box-shadow:0 3px 9px rgba(62,39,35,.08)!important;
}
body.report-sticky-mode .dashboard>.sales-actions,
body.report-sticky-mode .dashboard>.pre-export-bar{
 position:fixed!important;left:0!important;right:0!important;top:var(--report-toolbar-height,56px)!important;
 z-index:999!important;flex:0 0 auto!important;
 width:100%!important;max-width:100%!important;
 margin:0!important;padding:7px 10px!important;
 justify-content:flex-end!important;background:#f6f3f1!important;
 border-bottom:1px solid #e4d7cf!important;overflow:visible!important;
}
body.report-sticky-mode .dashboard>.pre-report{overflow:visible!important;min-height:0!important;flex:1 1 auto!important;}
body.report-sticky-mode .dashboard>#salesDashboardDocument{flex:0 0 auto!important;align-self:center!important;}
body.report-sticky-mode .dashboard>.sales-progress{position:sticky!important;top:calc(var(--report-toolbar-height,56px) + 50px)!important;z-index:998!important;}
@media(max-width:600px){
 body.report-sticky-mode .dashboard>.topbar{padding:8px!important;gap:7px!important;}
 body.report-sticky-mode .dashboard>.sales-actions,
 body.report-sticky-mode .dashboard>.pre-export-bar{padding:6px 8px!important;}
}
@media print{
 body.report-sticky-mode .dashboard>.topbar,
 body.report-sticky-mode .dashboard>.sales-actions,
 body.report-sticky-mode .dashboard>.pre-export-bar{position:static!important;box-shadow:none!important;}
}
</style>
