<section class="panel totalclean-panel"><div class="panel-head totalclean-head"><div><strong>Coffee Sales Summary</strong><span>Clean coffee · <?=date('d M Y',strtotime($from))?> — <?=date('d M Y',strtotime($to))?></span></div><div class="tc-summary-actions"><label for="tcSummaryGrouping">Summary by</label><select id="tcSummaryGrouping" aria-label="Coffee summary grouping"><option value="coffee">Coffee Type</option><option value="grade">Grades</option></select></div><div class="tc-export"><button type="button" id="tcExportBtn" class="tc-export-btn" title="Export Coffee Sales Summary">⇩ Export</button><div id="tcExportMenu" class="tc-export-menu"><button type="button" data-format="pdf">PDF</button><button type="button" data-format="xlsx">Excel</button><button type="button" data-format="doc">Word</button></div></div></div><div class="table-box"><table id="totalCleanSalesTable" class="totalclean-table">
<thead><tr><th rowspan="2">Type of Coffee</th><?php foreach($channels as$ch):?><th colspan="3"><?=htmlspecialchars($ch)?></th><?php endforeach;?><th colspan="3">Total</th></tr><tr><?php foreach($channels as$ch):?><th>Kg</th><th>USD</th><th>$/50kg</th><?php endforeach;?><th>Kg</th><th>USD</th><th>%</th></tr></thead><tbody>
<?php foreach($types as$ct):$rk=$rv=0;foreach($channels as$ch){$rk+=$totalClean[$ct][$ch]['kgs'];$rv+=$totalClean[$ct][$ch]['value'];}?><tr><td><?=htmlspecialchars($ct)?></td><?php foreach($channels as$ch):$x=$totalClean[$ct][$ch];?><td><?=nf($x['kgs'],2)?></td><td><?=nf($x['value'],2)?></td><td><?=nf($x['avg'],2)?></td><?php endforeach;?><td><?=nf($rk,2)?></td><td><?=nf($rv,2)?></td><td><?=nf(pct($rk,$tcGrandKg),2)?></td></tr><?php endforeach;?>
</tbody><tfoot><tr><td>Grand Total</td><?php foreach($channels as$ch):$x=$tcChannelTotals[$ch];?><td><?=nf($x['kgs'],2)?></td><td><?=nf($x['value'],2)?></td><td><?=nf($x['avg'],2)?></td><?php endforeach;?><td><?=nf($tcGrandKg,2)?></td><td><?=nf($tcGrandValue,2)?></td><td><?=$tcGrandKg>0?'100%':'0%'?></td></tr><tr class="share-row"><td>Channel Share</td><?php foreach($channels as$ch):$x=$tcChannelTotals[$ch];?><td><?=nf(pct($x['kgs'],$tcGrandKg),2)?></td><td colspan="2"></td><?php endforeach;?><td colspan="3"></td></tr></tfoot>
</table><table id="totalCleanGradeTable" class="totalclean-grade-table" hidden><thead><tr><th rowspan="2">Grade</th><th colspan="2"><?=htmlspecialchars($tcPreviousSeason)?></th><th colspan="2"><?=htmlspecialchars($tcCompareSeason)?></th></tr><tr><th>Weight (Tonnes)</th><th>Value (USD)</th><th>Weight (Tonnes)</th><th>Value (USD)</th></tr></thead><tbody>
<?php $tcGradeTotals=['previous'=>['kg'=>0,'usd'=>0],'current'=>['kg'=>0,'usd'=>0]];
foreach(['Arabica','Robusta'] as $family):
 $tcFamilyTotals=[];
 foreach(['previous'=>$tcPreviousGradeData,'current'=>$tcGradeData] as $key=>$dataset){$kg=0;$usd=0;foreach($dataset[$family] as $r){$kg+=$r['kg'];$usd+=$r['usd'];}$tcFamilyTotals[$key]=['kg'=>$kg,'usd'=>$usd];$tcGradeTotals[$key]['kg']+=$kg;$tcGradeTotals[$key]['usd']+=$usd;}
?><tr class="tc-grade-family"><td><?=strtoupper($family)?></td><?php foreach(['previous','current'] as $key):?><td><?=nf_clean($tcFamilyTotals[$key]['kg']/1000,3)?></td><td><?=nf_clean($tcFamilyTotals[$key]['usd'],2)?></td><?php endforeach;?></tr>
<?php $tcVisibleGrades=$tcGradeOrder[$family];foreach([$tcPreviousGradeData,$tcGradeData] as $dataset){foreach(array_keys($dataset[$family]) as $grade){if(!in_array($grade,$tcVisibleGrades,true))$tcVisibleGrades[]=$grade;}}
foreach($tcVisibleGrades as $grade):
 $prior=$tcPreviousGradeData[$family][$grade]??['kg'=>0,'usd'=>0];$current=$tcGradeData[$family][$grade]??['kg'=>0,'usd'=>0];
 if(str_starts_with($grade,'Unclassified') && abs((float)$prior['kg'])<0.000001 && abs((float)$prior['usd'])<0.000001 && abs((float)$current['kg'])<0.000001 && abs((float)$current['usd'])<0.000001)continue;
?><tr><td><?=htmlspecialchars($grade)?></td><td><?=nf_clean($prior['kg']/1000,3)?></td><td><?=nf_clean($prior['usd'],2)?></td><td><?=nf_clean($current['kg']/1000,3)?></td><td><?=nf_clean($current['usd'],2)?></td></tr><?php endforeach;endforeach;?></tbody><tfoot><tr><td>Grand Total</td><td><?=nf_clean($tcGradeTotals['previous']['kg']/1000,3)?></td><td><?=nf_clean($tcGradeTotals['previous']['usd'],2)?></td><td><?=nf_clean($tcGradeTotals['current']['kg']/1000,3)?></td><td><?=nf_clean($tcGradeTotals['current']['usd'],2)?></td></tr></tfoot></table></div>
<div id="tcGradeAnalysis" class="tc-grade-analysis" hidden>
 <div class="tc-grade-analysis-heading"><strong>Seasonal Grade Performance Analysis</strong><span>Comparison: <?=htmlspecialchars($tcPreviousSeason)?> vs <?=htmlspecialchars($tcCompareSeason)?> · shares based on sold weight and sales value</span></div>
 <div class="tc-grade-analysis-scroll"><table class="tc-grade-analysis-table"><thead><tr><th rowspan="2">Grade Group</th><th colspan="3"><?=htmlspecialchars($tcPreviousSeason)?></th><th colspan="3"><?=htmlspecialchars($tcCompareSeason)?></th><th colspan="2">Change</th></tr><tr><th>Weight (MT)</th><th>Volume Share</th><th>Value Share</th><th>Weight (MT)</th><th>Volume Share</th><th>Value Share</th><th>Volume Share (pp)</th><th>Weight (%)</th></tr></thead><tbody>
<?php foreach($tcGradeBands as $band):
 $prev=$tcGradeAnalysis['previous']['bands'][$band];$curr=$tcGradeAnalysis['current']['bands'][$band];
 if($band==='Unclassified' && $prev['kg']==0 && $curr['kg']==0 && $prev['usd']==0 && $curr['usd']==0)continue;
 $pShare=pct($prev['kg'],$tcGradeAnalysis['previous']['all']['kg']);$cShare=pct($curr['kg'],$tcGradeAnalysis['current']['all']['kg']);
 $weightGrowth=$prev['kg']>0?($curr['kg']-$prev['kg'])*100/$prev['kg']:null;
?><tr><td><?=htmlspecialchars($band)?></td><td><?=nf_clean($prev['kg']/1000,3)?></td><td><?=nf($pShare,2)?>%</td><td><?=nf(pct($prev['usd'],$tcGradeAnalysis['previous']['all']['usd']),2)?>%</td><td><?=nf_clean($curr['kg']/1000,3)?></td><td><?=nf($cShare,2)?>%</td><td><?=nf(pct($curr['usd'],$tcGradeAnalysis['current']['all']['usd']),2)?>%</td><td><?=($cShare-$pShare)>=0?'+':''?><?=nf($cShare-$pShare,2)?> pp</td><td><?=$weightGrowth===null?'N/A':(($weightGrowth>=0?'+':'').nf($weightGrowth,2).'%')?></td></tr><?php endforeach; ?>
 </tbody></table></div>
 <div class="tc-grade-analysis-notes">
 <?php foreach(['Arabica','Robusta'] as $family):
 $pa=$tcGradeAnalysis['previous']['families'][$family];$ca=$tcGradeAnalysis['current']['families'][$family];
 $oldTop=pct($pa['bands']['Top Grades']['kg'],$pa['all']['kg']);$newTop=pct($ca['bands']['Top Grades']['kg'],$ca['all']['kg']);
 $oldLow=pct($pa['bands']['Lower Grades']['kg'],$pa['all']['kg']);$newLow=pct($ca['bands']['Lower Grades']['kg'],$ca['all']['kg']);
 ?><p><strong><?=htmlspecialchars($family)?>:</strong> Higher-grade share <?=nf($oldTop,2)?>% → <?=nf($newTop,2)?>% (<?=($newTop-$oldTop)>=0?'+':''?><?=nf($newTop-$oldTop,2)?> pp); lower-grade share <?=nf($oldLow,2)?>% → <?=nf($newLow,2)?>% (<?=($newLow-$oldLow)>=0?'+':''?><?=nf($newLow-$oldLow,2)?> pp).</p><?php endforeach; ?>
 <p class="tc-grade-method"><strong>Classification:</strong> Top Grades = Arabica AAA, AA, A, AB, B, PB, C, H/A FAQ (FAQ / Standard); Robusta Over 18, Superior, FAQ (FAQ / Standard). Lower Grades = classified lower grades. Percentage-point changes compare shares of total sales weight; family shares use the respective coffee family's weight. A growth rate is N/A when the previous-season weight is zero.</p>
 </div>
</div></section>
