.fg-wrap{margin-top:18px}.fg-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-bottom:18px}.fg-metric{background:#fff;border:1px solid #e5d9cc;border-radius:12px;padding:18px}.fg-metric span{display:block;font-size:12px;color:#766457;font-weight:700}.fg-metric strong{display:block;margin-top:7px;font-size:23px;color:#473022}.fg-table-box{overflow:auto;max-height:65vh;border:1px solid #e4d8cb;border-radius:12px;background:white}.fg-table{width:100%;border-collapse:separate;border-spacing:0;font-size:13px}.fg-table th{position:sticky;top:0;background:#513629;color:white;padding:13px 15px;text-align:left;z-index:2}.fg-table td{padding:11px 15px;border-bottom:1px solid #eee7df}.fg-table td.num,.fg-table th.num{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.fg-table tbody tr:hover{background:#faf5ef}.fg-table .fg-region-name{font-weight:750;color:#493225;background:#f7f1e9;vertical-align:middle;border-right:1px solid #e7d9ca}.fg-table .fg-group-start td{border-top:2px solid #dfd0bf}.fg-table .fg-total td{background:#513629;color:#fff;font-weight:800}.fg-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:12px}.fg-head h2{font-size:17px;margin:0;color:#493225}.fg-head p{margin:5px 0 0;font-size:12px;color:#806c5e}.fg-export{border:1px solid #cdbba8;background:#fff;border-radius:8px;padding:9px 14px;color:#493225;font-weight:700;cursor:pointer}@media(max-width:650px){.fg-metrics{grid-template-columns:1fr}.fg-metric{padding:12px}}
