<script id="kagera-dashboard-view-script">
(function(){
 const chooser=document.getElementById('kageraDashboardView'),summary=document.getElementById('kageraSalesSummaryPanel'),rank=document.getElementById('kageraRankingPanels'),trend=document.getElementById('kageraTrendPanel');if(!chooser||!summary||!rank||!trend)return;
 window.setKageraDashboardView=function(view){if(!['summary','rankings','trend'].includes(view))view='summary';chooser.value=view;[[summary,'summary'],[rank,'rankings'],[trend,'trend']].forEach(([panel,key])=>{const active=view===key;panel.hidden=!active;panel.style.setProperty('display',active?'':'none',active?'':'important');if(active)panel.style.removeProperty('display')});try{sessionStorage.setItem('kagera_dashboard_view',view)}catch(e){}if(view==='trend')setTimeout(()=>window.dispatchEvent(new Event('resize')),60)};
 let initial='summary';try{initial=sessionStorage.getItem('kagera_dashboard_view')||'summary'}catch(e){}window.setKageraDashboardView(initial);
 const table=document.getElementById('kageraSalesSummaryTable');const rows=()=>Array.from(table.rows,tr=>Array.from(tr.cells,td=>td.textContent.trim()));
 const season=<?=json_encode($season)?>,period=<?=json_encode($summaryPeriods[$summaryPeriodValue]['label'])?>,range=<?=json_encode($from.' to '.$to)?>;
 const title='Kagera Auction - Sales Summary';const base='Kagera_Sales_Summary_'+season.replace('/','-')+'_'+<?=json_encode($summaryPeriodValue)?>;

 summary.querySelectorAll('[data-kagera-export]').forEach(button=>button.addEventListener('click',()=>{
 const type=button.dataset.kageraExport,data=rows();
 if(type==='xlsx'){if(!window.XLSX){alert('Excel export library is unavailable');return}const wb=XLSX.utils.book_new(),ws=XLSX.utils.aoa_to_sheet([['TANZANIA COFFEE BOARD'],[title],['Season: '+season,'Period: '+period,'Dates: '+range],[],...data]);ws['!cols']=[{wch:29},{wch:25},{wch:22},{wch:24},{wch:14}];XLSX.utils.book_append_sheet(wb,ws,'Sales Summary');XLSX.writeFile(wb,exportBase+'.xlsx');return}
 if(type==='doc'){const html='<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{font-family:Calibri,Arial;color:#483027}table{border-collapse:collapse;width:100%}th{background:#51382c;color:white}th,td{border:1px solid #ddd0c4;padding:7px;text-align:right}th:first-child,td:first-child{text-align:left}tr:last-child{background:#f0e7df;font-weight:bold}</style></head><body><h3>TANZANIA COFFEE BOARD</h3><h2>'+esc(title)+'</h2><p>Season: '+esc(season)+' | '+esc(period)+' | '+esc(range)+'</p><table>'+data.map((r,i)=>'<tr>'+r.map(c=>'<'+(i?'td':'th')+'>'+esc(c)+'</'+(i?'td':'th')+'>').join('')+'</tr>').join('')+'</table></body></html>';const blob=new Blob(['\ufeff',html],{type:'application/msword;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=exportBase+'.doc';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);return}
 if(type==='pdf'){if(!window.jspdf?.jsPDF){alert('PDF export library is unavailable');return}const doc=new window.jspdf.jsPDF({orientation:'landscape',unit:'mm',format:'a4'});doc.setTextColor(72,48,39);doc.setFontSize(12);doc.text('TANZANIA COFFEE BOARD',12,13);doc.setFontSize(15);doc.text(title,12,22);doc.setFontSize(9);doc.text('Season: '+season+' | '+period+' | '+range,12,30);if(typeof doc.autoTable!=='function'){alert('PDF table export library is unavailable');return}doc.autoTable({head:[data[0]],body:data.slice(1),startY:36,theme:'grid',styles:{fontSize:9,cellPadding:3},headStyles:{fillColor:[81,56,44]},didParseCell:function(x){if(x.section==='body'&&x.row.index===data.length-2){x.cell.styles.fontStyle='bold';x.cell.styles.fillColor=[240,231,223]}}});doc.save(exportBase+'.pdf')}
 }));
})();
</script>
