<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<script>
(function(){
 const picker=document.getElementById('directDashboardView'),summary=document.getElementById('directSummaryPanel'),rank=document.getElementById('directRankingPanels'),trend=document.getElementById('directTrendPanel');if(!picker||!summary||!rank||!trend)return;
 let chart;
 window.setDirectDashboardView=function(view){if(!['summary','rankings','trend'].includes(view))view='summary';picker.value=view;summary.hidden=view!=='summary';rank.hidden=view!=='rankings';trend.hidden=view!=='trend';try{sessionStorage.setItem('direct_dashboard_view',view)}catch(e){}if(view==='trend'){if(!chart&&window.Chart){const data=<?=json_encode($display==='direct'?$directTrend:[],JSON_NUMERIC_CHECK|JSON_UNESCAPED_UNICODE)?>;const ctx=document.getElementById('directSalesTrendChart');chart=new Chart(ctx,{data:{labels:data.map(x=>x.period),datasets:[{type:'bar',label:'Direct Export (MT)',data:data.map(x=>x['Direct Export']),yAxisID:'y'},{type:'bar',label:'Local Sale (MT)',data:data.map(x=>x['Local Sale']),yAxisID:'y'},{type:'bar',label:'Local Roast (MT)',data:data.map(x=>x['Local Roast']),yAxisID:'y'},{type:'line',label:'Sales Value (USD)',data:data.map(x=>x.value),yAxisID:'value',tension:.3}]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},scales:{y:{beginAtZero:true,title:{display:true,text:'Quantity (MT)'}},value:{position:'right',beginAtZero:true,title:{display:true,text:'Value (USD)'},grid:{drawOnChartArea:false}}}}})}setTimeout(()=>chart?.resize(),70)}};
 window.setDirectDashboardView(<?=json_encode($directView)?>);
 const table=document.getElementById('directSummaryTable');
 const esc=x=>String(x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
 rank.querySelectorAll('.direct-ranking-inline-filters').forEach(group=>{
  const suffix=group.dataset.rankParty==='buyer'?'buyer':'seller';
  const channel=group.querySelector('.direct-rank-channel'),party=group.querySelector('.direct-rank-party');
  const apply=changed=>{const url=new URL(location.href);url.searchParams.set('direct_view','rankings');url.searchParams.set('rank_'+suffix+'_channel',channel.value);url.searchParams.set('rank_'+suffix+'_party',changed==='channel'?'all':party.value);location.assign(url.toString())};
  channel.addEventListener('change',()=>apply('channel'));
  party.addEventListener('change',()=>apply('party'));
 });
 rank.querySelectorAll('.direct-panel-export').forEach(wrapper=>{
  const toggle=wrapper.querySelector('.direct-panel-export-toggle'),menu=wrapper.querySelector('.direct-panel-export-menu'),panel=wrapper.closest('.rank-export-panel');
  const close=()=>{menu.classList.remove('show');toggle.setAttribute('aria-expanded','false')};
  toggle.addEventListener('click',e=>{e.stopPropagation();rank.querySelectorAll('.direct-panel-export-menu.show').forEach(m=>{if(m!==menu){m.classList.remove('show');m.parentElement.querySelector('.direct-panel-export-toggle')?.setAttribute('aria-expanded','false')}});const opened=menu.classList.toggle('show');toggle.setAttribute('aria-expanded',String(opened))});
  menu.addEventListener('click',e=>e.stopPropagation());
  menu.querySelectorAll('[data-panel-export]').forEach(button=>button.addEventListener('click',()=>{
   const format=button.dataset.panelExport;
   const selector=format==='xlsx'?'.rank-export-button:not(.rank-word-button):not(.rank-pdf-button)':format==='doc'?'.rank-word-button':'.rank-pdf-button';
   close();panel.querySelector('.direct-original-export '+selector)?.click();
  }));
  document.addEventListener('click',e=>{if(!wrapper.contains(e.target))close()});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
 });

 const exportBtn=document.getElementById('directSummaryExportBtn'),exportMenu=document.getElementById('directSummaryExportMenu');
 exportBtn.addEventListener('click',e=>{e.stopPropagation();const open=exportMenu.classList.toggle('show');exportBtn.setAttribute('aria-expanded',String(open))});
 document.addEventListener('click',e=>{if(!exportBtn.parentElement.contains(e.target)){exportMenu.classList.remove('show');exportBtn.setAttribute('aria-expanded','false')}});
 const season=<?=json_encode($season)?>,period=<?=json_encode($summaryPeriods[$summaryPeriodValue]['label']??'')?>,range=<?=json_encode($from.' to '.$to)?>,title='Direct Sales - Consolidated Sales Summary',base='Direct_Sales_Summary_'+season.replace('/','-')+'_'+<?=json_encode($summaryPeriodValue??'all')?>;

 summary.querySelectorAll('[data-direct-export]').forEach(button=>button.addEventListener('click',()=>{exportMenu.classList.remove('show');exportBtn.setAttribute('aria-expanded','false');const type=button.dataset.directExport,copy=table.cloneNode(true);copy.querySelectorAll('[hidden]').forEach(el=>el.remove());const data=Array.from(copy.rows,tr=>Array.from(tr.cells,c=>c.textContent.trim()));const exportBase=base;
 if(type==='xlsx'){if(!window.XLSX)return alert('Excel export library unavailable');const wb=XLSX.utils.book_new(),ws=XLSX.utils.table_to_sheet(copy);XLSX.utils.sheet_add_aoa(ws,[['TANZANIA COFFEE BOARD'],[title],['Season: '+season+' | Period: '+period+' | Dates: '+range]],{origin:-1});ws['!cols']=[{wch:22},...Array.from({length:12},()=>({wch:17}))];XLSX.utils.book_append_sheet(wb,ws,'Sales Summary');XLSX.writeFile(wb,base+'.xlsx');return}
 if(type==='doc'){const html='<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial;color:#483027}table{border-collapse:collapse;width:100%}th{background:#51382c;color:white}th,td{border:1px solid #ddd0c4;padding:7px;text-align:right}th:first-child,td:first-child{text-align:left}tr:last-child{background:#f0e7df;font-weight:bold}</style></head><body><h3>TANZANIA COFFEE BOARD</h3><h2>'+esc(title)+'</h2><p>'+esc(season)+' | '+esc(period)+' | '+esc(range)+'</p><table>'+data.map((r,i)=>'<tr>'+r.map(c=>'<'+(i?'td':'th')+'>'+esc(c)+'</'+(i?'td':'th')+'>').join('')+'</tr>').join('')+'</table></body></html>';const url=URL.createObjectURL(new Blob(['\ufeff',html],{type:'application/msword;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=base+'.doc';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);return}
 if(type==='pdf'){if(!window.jspdf?.jsPDF)return alert('PDF export library unavailable');const doc=new window.jspdf.jsPDF({orientation:'landscape',unit:'mm',format:'a4'});doc.setFontSize(12);doc.text('TANZANIA COFFEE BOARD',12,13);doc.setFontSize(15);doc.text(title,12,22);doc.setFontSize(9);doc.text('Season: '+season+' | '+period+' | '+range,12,30);if(!doc.autoTable)return alert('PDF table library unavailable');doc.autoTable({html:copy,startY:36,theme:'grid',styles:{fontSize:7,cellPadding:2},headStyles:{fillColor:[81,56,44]},margin:{left:6,right:6}});doc.save(base+'.pdf')}
 }));
})();
</script>


<script id="auction-ranking-downloads">
(function(){
 const safe=s=>String(s||'Ranking').replace(/[^a-z0-9_-]+/gi,'_').replace(/^_+|_+$/g,'').slice(0,90);
 const season=<?=json_encode($season)?>,channel=<?=json_encode($display)?>;
 const range=<?=json_encode(date('d M Y',strtotime($from)).' — '.date('d M Y',strtotime($to)))?>;
 const period=<?=json_encode($summaryPeriods[$summaryPeriodValue]['label'])?>;
 document.querySelectorAll('.rank-export-panel').forEach(panel=>{
  const table=panel.querySelector('table'),title=panel.querySelector('.panel-head strong')?.textContent.trim()||'Ranking';
  const base=safe(channel+'_'+title+'_'+season+'_'+period);
  const toggle=panel.querySelector('.ranking-other-toggle');
  toggle?.addEventListener('click',()=>{
   const expand=toggle.getAttribute('aria-expanded')!=='true';
   toggle.setAttribute('aria-expanded',String(expand));
   toggle.querySelector('.ranking-other-hint').textContent=expand?'Hide details':'Show details';
   panel.querySelectorAll('.ranking-other-detail').forEach(tr=>{tr.hidden=!expand;});
  });
  const rows=()=>[...table.rows].filter(tr=>!tr.hidden && !(tr.classList.contains('ranking-other-detail')&&tr.hasAttribute('hidden'))).map((tr,i)=>{
   const cells=[...tr.cells].map(td=>{const clone=td.cloneNode(true);clone.querySelectorAll('.rank,.ranking-other-hint,.ranking-other-chevron').forEach(el=>el.remove());return clone.textContent.trim().replace(/\s+/g,' ')});
   if(i===0)return ['S/No',...cells];
   const rank=tr.querySelector('td:first-child .rank')?.textContent.trim()||'';
   return [rank,...cells];
  });
  const filename=ext=>base+'.'+ext;
  panel.querySelector('.rank-export-button:not(.rank-word-button):not(.rank-pdf-button)')?.addEventListener('click',()=>{
   if(!window.XLSX){alert('Excel library unavailable. Refresh the page and retry.');return}
   const data=rows(),book=XLSX.utils.book_new();
   const sheet=XLSX.utils.aoa_to_sheet([['TANZANIA COFFEE BOARD'],[title],['Season: '+season,'Period: '+period,'Dates: '+range],[],...data]);
   sheet['!cols']=data[0].map((_,i)=>({wch:i===0?8:Math.min(52,Math.max(17,...data.map(r=>String(r[i]||'').length)))}));
   XLSX.utils.book_append_sheet(book,sheet,'Top 15');XLSX.writeFile(book,filename('xlsx'));
  });
  panel.querySelector('.rank-word-button')?.addEventListener('click',()=>{
   const escape=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
   const data=rows();const html='<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{font-family:Calibri,Arial,sans-serif;color:#38271f}h2{color:#50372c}table{border-collapse:collapse;width:100%;font-size:10pt}td,th{border:1px solid #d7cac2;padding:5px;text-align:right}td:first-child,th:first-child{text-align:center;width:45px}td:nth-child(2),th:nth-child(2){text-align:left}tr:first-child{background:#50372c;color:white;font-weight:bold}tr:last-child{background:#f1e9e3;font-weight:bold}</style></head><body><h3>TANZANIA COFFEE BOARD</h3><h2>'+escape(title)+'</h2><p>Season: '+escape(season)+' | '+escape(period)+' | '+escape(range)+'</p><table>'+data.map((r,i)=>'<tr>'+r.map(c=>'<'+(i===0?'th':'td')+'>'+escape(c)+'</'+(i===0?'th':'td')+'>').join('')+'</tr>').join('')+'</table></body></html>';
   const blob=new Blob(['\ufeff',html],{type:'application/msword;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename('doc');document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);
  });
  panel.querySelector('.rank-pdf-button')?.addEventListener('click',()=>{
   if(!window.jspdf?.jsPDF){alert('PDF library unavailable. Refresh and retry.');return}
   const data=rows(),doc=new window.jspdf.jsPDF({orientation:'landscape',unit:'mm',format:'a4'});
   doc.setFontSize(11);doc.setTextColor(65,44,35);doc.text('TANZANIA COFFEE BOARD',12,13);doc.setFontSize(15);doc.text(title,12,21);doc.setFontSize(9);doc.text('Season: '+season+'   |   '+period+'   |   '+range,12,28);
   if(typeof doc.autoTable!=='function'){alert('PDF table library unavailable. Refresh and retry.');return}
   doc.autoTable({head:[data[0]],body:data.slice(1),startY:34,theme:'grid',styles:{fontSize:8,cellPadding:2,overflow:'linebreak'},headStyles:{fillColor:[75,52,44],textColor:255},alternateRowStyles:{fillColor:[249,246,243]},didParseCell:function(info){if(info.section==='body'&&info.row.index===data.length-2){info.cell.styles.fontStyle='bold';info.cell.styles.fillColor=[239,231,224]}}});
   doc.save(filename('pdf'));
  });
 });
})();
</script>

<script>
(function(){
 const sel=document.getElementById('tcAnalysisType'),box=document.getElementById('tcAnalysisTable'),
 search=document.getElementById('tcPartySearch'),status=document.getElementById('tcAnalysisStatus'),
 exportBtn=document.getElementById('tcAnalysisExportBtn'),exportMenu=document.getElementById('tcAnalysisExportMenu');
 if(!sel||!box)return;
 const D=<?=json_encode($display==='totalclean'?$tcAnalytics:[],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
 const M={
  buyer_channel:{party:'buyer',dim:'channel',partyLabel:'Buyer',dimLabel:'Sales Channel'},
  supplier_channel:{party:'supplier',dim:'channel',partyLabel:'Supplier / Seller',dimLabel:'Sales Channel'},
  buyer_region:{party:'buyer',dim:'region',partyLabel:'Buyer',dimLabel:'Region'},
  supplier_region:{party:'supplier',dim:'region',partyLabel:'Supplier / Seller',dimLabel:'Region'},
  buyer_type:{party:'buyer',dim:'coffee_type',partyLabel:'Buyer',dimLabel:'Coffee Type'},
  supplier_type:{party:'supplier',dim:'coffee_type',partyLabel:'Supplier / Seller',dimLabel:'Coffee Type'}
 };
 const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
 const fmt=(v,d=2)=>{v=Number(v)||0;return v.toLocaleString(undefined,{minimumFractionDigits:0,maximumFractionDigits:Number.isInteger(v)?0:Math.min(d,2)})};
 let expanded=false,current={};

 function build(){
  const cfg=M[sel.value], all=D[sel.value]||[], q=(search?.value||'').trim().toLowerCase();
  const partyTotals=new Map(),cells=new Map(),dimTotals=new Map();
  all.forEach(r=>{
   const p=r[cfg.party]||'Unspecified',d=r[cfg.dim]||'Unspecified',kg=+r.kgs||0,val=+r.value_usd||0;
   let x=partyTotals.get(p)||{kg:0,val:0};x.kg+=kg;x.val+=val;partyTotals.set(p,x);
   x=cells.get(p+'\x1f'+d)||{kg:0,val:0};x.kg+=kg;x.val+=val;cells.set(p+'\x1f'+d,x);
   x=dimTotals.get(d)||{kg:0,val:0};x.kg+=kg;x.val+=val;dimTotals.set(d,x);
  });
  const allParties=[...partyTotals.keys()].sort((a,b)=>partyTotals.get(b).kg-partyTotals.get(a).kg);
  const filtered=q?allParties.filter(p=>p.toLowerCase().includes(q)):allParties;
  const top=q?filtered:allParties.slice(0,10), others=q?[]:allParties.slice(10);
  let dims=[...dimTotals.keys()];
  if(cfg.dim==='channel'){const o=['Auction Sale','Direct Export','Local Sale','Local Roast'];dims.sort((a,b)=>(o.indexOf(a)<0?999:o.indexOf(a))-(o.indexOf(b)<0?999:o.indexOf(b)));}
  else dims.sort((a,b)=>dimTotals.get(b).kg-dimTotals.get(a).kg);
  current={cfg,allParties,filtered,top,others,dims,partyTotals,cells,q};
 }

 function row(p,label,cls=''){
  const {dims,partyTotals,cells}=current,pt=partyTotals.get(p)||{kg:0,val:0};
  let h=`<tr class="${cls}"><td>${label}</td><td title="${esc(p)}">${esc(p)}</td>`;
  dims.forEach(d=>{const c=cells.get(p+'\x1f'+d)||{kg:0,val:0};h+=`<td>${fmt(c.kg,3)}</td><td>${fmt(c.val,2)}</td>`});
  return h+`<td class="pivot-total">${fmt(pt.kg,3)}</td><td class="pivot-total">${fmt(pt.val,2)}</td></tr>`;
 }
 function aggregate(parties){
  const a={kg:0,val:0,by:{}};
  current.dims.forEach(d=>a.by[d]={kg:0,val:0});
  parties.forEach(p=>{const pt=current.partyTotals.get(p)||{kg:0,val:0};a.kg+=pt.kg;a.val+=pt.val;current.dims.forEach(d=>{const c=current.cells.get(p+'\x1f'+d)||{kg:0,val:0};a.by[d].kg+=c.kg;a.by[d].val+=c.val})});
  return a;
 }
 function aggRow(name,a,cls=''){
  let h=`<tr class="${cls}"><td></td><td>${esc(name)}</td>`;
  current.dims.forEach(d=>h+=`<td>${fmt(a.by[d].kg,3)}</td><td>${fmt(a.by[d].val,2)}</td>`);
  return h+`<td>${fmt(a.kg,3)}</td><td>${fmt(a.val,2)}</td></tr>`;
 }
 function draw(){
  build();const {cfg,top,others,dims,q,filtered,allParties}=current;
  let h=`<table id="tcPivotExportTable" class="tc-pivot-table"><thead><tr><th rowspan="2">#</th><th rowspan="2">${esc(cfg.partyLabel)}</th>`;
  dims.forEach(d=>h+=`<th colspan="2">${esc(d)}</th>`);h+='<th colspan="2">Total</th></tr><tr>';
  dims.forEach(()=>h+='<th>Kg</th><th>Value USD</th>');h+='<th>Kg</th><th>Value USD</th></tr></thead><tbody>';
  top.forEach((p,i)=>h+=row(p,i+1));
  if(!q&&others.length){
   const a=aggregate(others);
   h+=`<tr id="tcOtherToggle" class="tc-other-row"><td>${expanded?'−':'+'}</td><td class="tc-expand">Other (${others.length} ${cfg.partyLabel.toLowerCase()}${others.length===1?'':'s'})</td>`;
   dims.forEach(d=>h+=`<td>${fmt(a.by[d].kg,3)}</td><td>${fmt(a.by[d].val,2)}</td>`);
   h+=`<td>${fmt(a.kg,3)}</td><td>${fmt(a.val,2)}</td></tr>`;
   if(expanded)others.forEach((p,i)=>h+=row(p,11+i,'tc-detail-row'));
  }
  if(q&&!filtered.length)h+=`<tr><td colspan="${4+dims.length*2}" style="text-align:center">No matching ${esc(cfg.partyLabel.toLowerCase())} found.</td></tr>`;
  h+='</tbody><tfoot>'+aggRow(q?`Filtered Total (${filtered.length})`:'Overall Total',aggregate(q?filtered:allParties),'tc-overall-row')+'</tfoot></table>';
  box.innerHTML=h;
  status.textContent=q?`${filtered.length} matching ${cfg.partyLabel.toLowerCase()} record(s) · export will use the filtered result.`:`Showing Top ${Math.min(10,allParties.length)} of ${allParties.length} ${cfg.partyLabel.toLowerCase()} records · ${others.length} other${others.length===1?'':'s'}.`;
  document.getElementById('tcOtherToggle')?.addEventListener('click',()=>{expanded=!expanded;draw()});
 }
 sel.addEventListener('change',()=>{expanded=false;if(search)search.value='';draw()});
 search?.addEventListener('input',()=>{expanded=false;draw()});
 draw();

 if(exportBtn&&exportMenu){
  exportBtn.addEventListener('click',e=>{e.stopPropagation();exportMenu.classList.toggle('show')});
  document.addEventListener('click',()=>exportMenu.classList.remove('show'));
  const exportTable=()=>document.getElementById('tcPivotExportTable');
  const fname=ext=>`Clean_Coffee_${sel.value}_${search?.value?'Filtered':'Top10'}_<?=preg_replace('/[^0-9A-Za-z_-]/','_', $season)?>.${ext}`;
  function xlsx(){
   const table=exportTable();if(!table||!window.XLSX)return;
   const wb=XLSX.utils.table_to_book(table,{sheet:'Analysis',raw:true});
   const ws=wb.Sheets.Analysis,range=XLSX.utils.decode_range(ws['!ref']);
   for(let r=2;r<=range.e.r;r++)for(let c=2;c<=range.e.c;c++){const a=XLSX.utils.encode_cell({r,c}),cell=ws[a];if(!cell)continue;const n=Number(String(cell.v).replace(/,/g,''));if(Number.isFinite(n)){cell.v=n;cell.t='n';cell.z='#,##0.00####';}}
   XLSX.writeFile(wb,fname('xlsx'));
  }
  function pdf(){
   const table=exportTable();if(!table||!window.jspdf)return;const {jsPDF}=window.jspdf,doc=new jsPDF({orientation:'landscape',unit:'mm',format:'a4'});
   doc.setFontSize(11);doc.text('Clean Coffee Buyer / Supplier-Seller Analysis',10,10);
   doc.setFontSize(7);doc.text(`Sale Season <?=htmlspecialchars($season)?> · ${sel.options[sel.selectedIndex].text}${search?.value?' · Filter: '+search.value:''}`,10,15);
   doc.autoTable({html:table,startY:19,theme:'grid',styles:{fontSize:4.8,cellPadding:.8},headStyles:{fontStyle:'bold'},footStyles:{fontStyle:'bold'}});
   doc.save(fname('pdf'));
  }
  function word(){
   const table=exportTable();if(!table)return;const clone=table.cloneNode(true);clone.querySelectorAll('th,td').forEach(c=>c.style.cssText='border:1px solid #555;padding:3px;font-family:Arial;font-size:8pt');clone.style.cssText='border-collapse:collapse;width:100%';
   const html=`<html><head><meta charset="utf-8"></head><body><h3>Clean Coffee Buyer / Supplier-Seller Analysis</h3><p>Sale Season <?=htmlspecialchars($season)?> · ${esc(sel.options[sel.selectedIndex].text)}${search?.value?' · Filter: '+esc(search.value):''}</p>${clone.outerHTML}
</body></html>`;
   const b=new Blob(['\ufeff',html],{type:'application/msword'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=fname('doc');a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);
  }
  exportMenu.addEventListener('click',e=>{const f=e.target.dataset.format;if(!f)return;e.stopPropagation();exportMenu.classList.remove('show');f==='xlsx'?xlsx():f==='pdf'?pdf():word()});
 }
})();
</script>

<script>
(function(){
 const btn=document.getElementById('tcExportBtn'),menu=document.getElementById('tcExportMenu'),coffeeTable=document.getElementById('totalCleanSalesTable'),gradeTable=document.getElementById('totalCleanGradeTable'),grouping=document.getElementById('tcSummaryGrouping');
 let table=coffeeTable;
 if(grouping&&gradeTable){const analysis=document.getElementById('tcGradeAnalysis');const syncGradeView=()=>{const grade=grouping.value==='grade';table=grade?gradeTable:coffeeTable;gradeTable.hidden=!grade;coffeeTable.hidden=grade;if(analysis)analysis.hidden=!grade;};grouping.addEventListener('change',syncGradeView);syncGradeView();}
 if(!btn||!menu||!table)return;
 const season=<?=json_encode($season)?>;
 const safe=s=>String(s).replace(/[^A-Za-z0-9_-]+/g,'_');
 const filename=ext=>`Coffee_Sales_Summary_${grouping?.value==='grade'?'By_Grades_':'By_Coffee_Type_'}${safe(season)}.${ext}`;
 btn.addEventListener('click',e=>{e.stopPropagation();menu.classList.toggle('show')});
 document.addEventListener('click',()=>menu.classList.remove('show'));

 function matrix(){
   return [...table.rows].map(r=>[...r.cells].map(c=>c.innerText.trim()));
 }
 function numeric(v,percent=false){
   if(v===''||v==='-')return null;
   const n=Number(String(v).replace(/,/g,'').replace(/%/g,'').trim());
   return Number.isFinite(n)?(percent?n/100:n):v;
 }
 function exportExcel(){
   if(!window.XLSX){alert('Excel export library is not available.');return}
   const aoa=matrix();
   if(table===gradeTable){const ws=XLSX.utils.aoa_to_sheet(aoa);for(let r=2;r<aoa.length;r++)for(let c=1;c<=4;c++){const a=XLSX.utils.encode_cell({r,c}),cell=ws[a];if(cell){const n=numeric(cell.v);if(typeof n==='number'){cell.v=n;cell.t='n';cell.z='#,##0.00#';}}}ws['!cols']=[{wch:45},{wch:20},{wch:22},{wch:20},{wch:22}];const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Sales by Grade');XLSX.writeFile(wb,filename('xlsx'));return;}
   const ws=XLSX.utils.aoa_to_sheet(aoa);
   const range=XLSX.utils.decode_range(ws['!ref']);
   // Rows 3 onward contain data. First column is text; all remaining populated cells are numeric.
   for(let r=2;r<=range.e.r;r++){
     for(let c=1;c<=range.e.c;c++){
       const a=XLSX.utils.encode_cell({r,c}),cell=ws[a];
       if(!cell||cell.v==='')continue;
       const isPct=(c===range.e.c)||(aoa[r]&&aoa[r][0]==='Channel Share'&&(c===1||c===4||c===7||c===10));
       const n=numeric(cell.v,isPct);
       if(typeof n==='number'){cell.v=n;cell.t='n';cell.z=isPct?'0.00%':'#,##0.00####';}
     }
   }
   ws['!cols']=[{wch:18},...Array(15).fill({wch:12})];
   const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Coffee Sales Summary');
   XLSX.writeFile(wb,filename('xlsx'),{cellStyles:true});
 }
 function exportPDF(){
   if(!window.jspdf||!window.jspdf.jsPDF){alert('PDF export library is not available.');return}
   const {jsPDF}=window.jspdf,doc=new jsPDF({orientation:'landscape',unit:'mm',format:'a4'});
   doc.setFont('helvetica','bold');doc.setFontSize(13);doc.text(table===gradeTable?'Coffee Sales Summary by Grades':'Coffee Sales Summary',14,13);
   doc.setFont('helvetica','normal');doc.setFontSize(8);doc.text(`Clean coffee · Sale Season ${season}`,14,18);
   doc.autoTable({html:table,startY:22,theme:'grid',
     styles:{fontSize:5.7,cellPadding:1.2,textColor:[40,31,27],lineColor:[91,64,51],lineWidth:.15,fillColor:false},
     headStyles:{fontStyle:'bold',textColor:[58,39,30],fillColor:[245,240,236],lineWidth:.25},
     footStyles:{fontStyle:'bold',textColor:[58,39,30],fillColor:[250,247,245],lineWidth:.25},
     columnStyles:{0:{cellWidth:table===gradeTable?80:24,halign:'left'}},
     didParseCell:d=>{if(d.column.index>0)d.cell.styles.halign='right';}
   });
   doc.save(filename('pdf'));
 }
 function exportWord(){
   const cloned=table.cloneNode(true);
   cloned.querySelectorAll('th,td').forEach(c=>c.setAttribute('style','border:1px solid #5b4033;padding:4px;font-family:Arial;font-size:9pt;'));
   cloned.setAttribute('style','border-collapse:collapse;width:100%;');
   const html=`<!doctype html><html><head><meta charset="utf-8"><title>Coffee Sales Summary</title></head><body><h2 style="font-family:Arial;color:#4b2e20;margin-bottom:3px">Coffee Sales Summary</h2><div style="font-family:Arial;font-size:9pt;margin-bottom:10px">Clean coffee · Sale Season ${season}</div>${cloned.outerHTML}</body></html>`;
   const blob=new Blob(['\ufeff',html],{type:'application/msword'});
   const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename('doc');document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);
 }
 menu.addEventListener('click',e=>{const f=e.target.dataset.format;if(!f)return;e.stopPropagation();menu.classList.remove('show');if(f==='pdf')exportPDF();else if(f==='xlsx')exportExcel();else exportWord();});
})();
</script>

<script>
const auctionTrend=<?=json_encode(in_array($display,['sales','preauction','direct','totalclean'],true)?[]:$auctionTrend,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,cleanMode=<?=json_encode($display==='clean')?>,ctx=document.getElementById('auctionTrendChart');
if(ctx&&window.Chart){const datasets=cleanMode?[
{type:'bar',label:'Quantity Sold (kg)',data:auctionTrend.map(r=>Number(r.qty)||0),yAxisID:'yQty',borderWidth:0,maxBarThickness:24},
{type:'line',label:'Weighted Avg Price (USD/50kg)',data:auctionTrend.map(r=>r.avg_price===null?null:Number(r.avg_price)),yAxisID:'yPrice',borderWidth:2,pointRadius:2,tension:.25}
]:[
{type:'bar',label:'Dry Cherry Qty (kg)',data:auctionTrend.map(r=>Number(r.dry_qty)||0),yAxisID:'yQty',borderWidth:0,maxBarThickness:18},
{type:'bar',label:'Clean Coffee Qty (kg)',data:auctionTrend.map(r=>Number(r.clean_qty)||0),yAxisID:'yQty',borderWidth:0,maxBarThickness:18},
{type:'line',label:'Dry Cherry Avg Price',data:auctionTrend.map(r=>r.dry_avg_price===null?null:Number(r.dry_avg_price)),yAxisID:'yPrice',borderWidth:2,pointRadius:2,tension:.25},
{type:'line',label:'Clean Coffee Avg Price',data:auctionTrend.map(r=>r.clean_avg_price===null?null:Number(r.clean_avg_price)),yAxisID:'yPrice',borderWidth:2,pointRadius:2,tension:.25}];
const compactChart=()=>window.innerWidth<640;\nnew Chart(ctx,{data:{labels:auctionTrend.map(r=>'A'+r.auction_no),datasets},options:{responsive:true,maintainAspectRatio:false,resizeDelay:120,layout:{padding:{top:5,right:5,bottom:3,left:3}},interaction:{mode:'index',intersect:false},plugins:{legend:{position:'top',labels:{boxWidth:10,boxHeight:10,font:{size:10},padding:10}}},scales:{x:{grid:{display:false},ticks:{font:{size:9},autoSkip:true,maxTicksLimit:compactChart()?6:18,maxRotation:0,minRotation:0},title:{display:true,text:'Auction No.',font:{size:8}}},yQty:{position:'left',beginAtZero:true,title:{display:true,text:'Quantity sold (kg)',font:{size:8}},ticks:{font:{size:8},callback:v=>Number(v).toLocaleString()}},yPrice:{position:'right',title:{display:true,text:cleanMode?'Avg. price (USD/50kg)':'Avg. price (TZS/kg)',font:{size:8}},grid:{drawOnChartArea:false},ticks:{font:{size:8},callback:v=>Number(v).toLocaleString()}}}}});}
</script>

<script>
(function(){
 const btn=document.getElementById('preExportBtn'),menu=document.getElementById('preExportMenu'),paper=document.getElementById('preAuctionReportPaper');
 if(!btn||!menu||!paper)return;
 btn.addEventListener('click',e=>{e.stopPropagation();menu.classList.toggle('show')});
 document.addEventListener('click',()=>menu.classList.remove('show'));
 const season=<?=json_encode($season??'')?>;
 const base=<?=json_encode($salesReportView==='wizara'?'Wizara_Summary_Report_':'Pre_Auction_Report_')?>+String(season||'').replace('/','-');
 function word(){const html='<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial;font-size:10pt}h1{text-align:center;font-size:14pt}h2{font-size:12pt}h3{font-size:11pt}table{border-collapse:collapse;width:100%;margin:6px 0 14px}th,td{border:1px solid #555;padding:4px}th{background:#d9e8f6;text-align:center}td{text-align:right}td:first-child,td:nth-child(2){text-align:left}.gt{font-weight:bold}</style></head><body>'+paper.innerHTML.replace(/<div class="pre-export-bar"[\s\S]*?<\/div>\s*<\/div>/,'')+'</body></html>';const b=new Blob(['\ufeff',html],{type:'application/msword'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=base+'.doc';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
 function excel(){if(!window.XLSX){alert('Excel export library is not available.');return}const wb=XLSX.utils.book_new();paper.querySelectorAll('table').forEach((t,i)=>{const ws=XLSX.utils.table_to_sheet(t,{raw:true});XLSX.utils.book_append_sheet(wb,ws,'Table '+(i+1))});XLSX.writeFile(wb,base+'.xlsx')}
 async function pdf(){
  if(!window.html2canvas||!window.jspdf){alert('PDF export library is not available.');return}
  menu.classList.remove('show');
  const oldWidth=paper.style.width,oldMax=paper.style.maxWidth,oldShadow=paper.style.boxShadow;
  preApplyTableAlignment(paper);
  paper.classList.add('pdf-exporting');
  paper.style.width='794px';
  paper.style.maxWidth='794px';
  paper.style.boxShadow='none';
  try{
    if(document.fonts&&document.fonts.ready) await document.fonts.ready;
    const scale=Math.max(2.5,Math.min(3.2,(window.devicePixelRatio||1)*2));
    const canvas=await html2canvas(paper,{
      scale,
      backgroundColor:'#ffffff',
      useCORS:true,
      allowTaint:false,
      logging:false,
      imageTimeout:15000,
      removeContainer:true,
      scrollX:0,
      scrollY:-window.scrollY,
      windowWidth:794,
      onclone:doc=>{
        const p=doc.getElementById('preAuctionReportPaper');
        if(p){
          p.style.width='794px';
          p.style.maxWidth='794px';
          p.style.boxShadow='none';
          p.style.opacity='1';
          p.querySelectorAll('*').forEach(el=>{
            el.style.opacity='1';
            el.style.textShadow='none';
            el.style.filter='none';
          });
        }
      },
      ignoreElements:e=>e.classList&&e.classList.contains('pre-export-bar')
    });
    const {jsPDF}=window.jspdf;
    const doc=new jsPDF({orientation:'portrait',unit:'mm',format:'a4',compress:true,putOnlyUsedFonts:true});
    const margin=6,pw=doc.internal.pageSize.getWidth()-margin*2,ph=doc.internal.pageSize.getHeight()-margin*2;
    const pagePx=Math.floor(canvas.width*(ph/pw));
    let y=0,page=0;
    while(y<canvas.height){
      const hpx=Math.min(pagePx,canvas.height-y);
      const slice=document.createElement('canvas');
      slice.width=canvas.width;
      slice.height=hpx;
      const ctx=slice.getContext('2d',{alpha:false});
      ctx.fillStyle='#ffffff';
      ctx.fillRect(0,0,slice.width,slice.height);
      ctx.drawImage(canvas,0,y,canvas.width,hpx,0,0,canvas.width,hpx);
      if(page++) doc.addPage();
      const hmm=hpx*pw/canvas.width;
      /* PNG is lossless and avoids the faded/soft JPEG text seen previously. */
      doc.addImage(slice.toDataURL('image/png'),'PNG',margin,margin,pw,hmm,undefined,'FAST');
      y+=hpx;
    }
    doc.save(base+'.pdf');
  }finally{
    paper.classList.remove('pdf-exporting');
    paper.style.width=oldWidth;
    paper.style.maxWidth=oldMax;
    paper.style.boxShadow=oldShadow;
  }
 }
 menu.addEventListener('click',async e=>{const f=e.target.closest('[data-format]')?.dataset.format;if(!f)return;e.stopPropagation();menu.classList.remove('show');btn.disabled=true;
 const task=window.reportTask.start('Exporting Pre-Auction Report','Preparing '+f.toUpperCase()+' report…');
 try{window.reportTask.update(20,'Preparing report tables and formatting…');await new Promise(resolve=>requestAnimationFrame(()=>setTimeout(resolve,40)));
 if(f==='pdf'){window.reportTask.update(45,'Rendering high-resolution PDF pages…');await pdf();}
 else if(f==='xlsx'){window.reportTask.update(70,'Generating Excel workbook…');excel();}
 else{window.reportTask.update(70,'Generating Word document…');word();}
 window.reportTask.update(95,'Saving report file…');window.reportTask.end(task,false);
 }catch(err){console.error(err);window.reportTask.end(task,true);alert('Report export failed: '+err.message);}finally{btn.disabled=false;}
 });
})();

function preApplyTableAlignment(root){
  root=root||document;
  root.querySelectorAll('.pre-report table').forEach(table=>{
    table.querySelectorAll('th').forEach(cell=>{
      cell.classList.remove('pre-text-cell','pre-number-cell');
      cell.classList.add('pre-header-cell');
    });
    table.querySelectorAll('td').forEach(cell=>{
      cell.classList.remove('pre-text-cell','pre-number-cell','pre-header-cell');
      const raw=(cell.textContent||'').replace(/\u00a0/g,' ').trim();
      const cleaned=raw.replace(/,/g,'').replace(/\s+/g,' ');
      // Numeric if cell consists of a number/currency-number/ dash only.
      const numeric=/^(?:[-–—]|(?:USD|TZS|\$)?\s*[-+]?\d+(?:\.\d+)?(?:\s*(?:kg|kgs|mt|usd|tzs))?)$/i.test(cleaned);
      cell.classList.add(numeric?'pre-number-cell':'pre-text-cell');
    });
  });
}
document.addEventListener('DOMContentLoaded',()=>preApplyTableAlignment(document));
</script>

