.sales-actions #salesExportOptions{position:absolute!important;right:0!important;top:calc(100% + 4px)!important;z-index:100!important;min-width:145px!important;padding:4px!important;border:1px solid #d8cec8!important;border-radius:6px!important;background:#fff!important;box-shadow:0 7px 20px rgba(0,0,0,.14)!important}
.sales-actions #salesExportOptions[hidden]{display:none!important}
.sales-actions #salesExportOptions:not([hidden]){display:block!important}
.sales-actions #salesExportOptions button{display:block!important;width:100%!important;padding:9px 10px!important;border:0!important;background:transparent!important;text-align:left!important;color:#4b2e20!important;font-size:12px!important;cursor:pointer!important}
.sales-actions #salesExportOptions button:hover{background:#f4e8dc!important}
.pre-report{min-width:0!important;max-width:100%!important;overflow-x:hidden!important}
.pre-report .pre-paper{box-sizing:border-box!important;max-width:min(980px,100%)!important;min-width:0!important}
.pre-report .pre-scroll{max-width:100%!important;overflow-x:auto!important;-webkit-overflow-scrolling:touch!important}
.pre-report .pre-scroll table{width:100%!important}
#salesDashboardDocument{max-width:min(1023px,100%)!important;min-width:0!important}
@media(max-width:720px){.pre-report .pre-paper{padding:16px 12px 26px!important}.pre-report .pre-paper h1{font-size:clamp(13px,3.5vw,17px)!important}.pre-report .pre-paper h2{font-size:clamp(12px,3vw,15px)!important}.pre-report .pre-paper p{font-size:12px!important;line-height:1.55!important}.pre-report .pre-scroll table{min-width:560px!important}.sales-actions{padding:0 2px!important}.sales-actions #salesExportButton{font-size:12px!important}}
@media(max-width:420px){.pre-report .pre-paper{padding:12px 9px 22px!important}.pre-report .pre-scroll table{min-width:520px!important}.pre-export-bar{justify-content:flex-end!important}}
@media print{.sales-actions,.pre-export-bar{display:none!important}}
</style>
<style id="sales-background-readiness-guard">
/* Never expose report figures on an empty/unpainted poster. */
#salesDashboardDocument.sales-ppt:not(.sales-background-ready) .sales-ppt-body{visibility:hidden!important}
#salesDashboardDocument.sales-ppt.sales-background-failed .sales-ppt-body{visibility:hidden!important}
#salesDashboardDocument.sales-ppt.sales-background-failed::after{content:"The sales report background could not be loaded. Please refresh the page.";position:absolute;top:42%;left:8%;width:84%;padding:18px 12px;box-sizing:border-box;text-align:center;color:#603923;background:#fff9f1;border:1px solid #c8a88c;border-radius:8px;font:600 14px/1.5 Arial,sans-serif;z-index:8}
@media print{#salesDashboardDocument.sales-ppt:not(.sales-background-ready) .sales-ppt-body{visibility:hidden!important}}
</style>
<style id="sales-iframe-responsive-patch">

/* Responsive report canvas: typography scales with the actual iframe width,
   including after the parent sidebar changes its width. */
#salesDashboardDocument.sales-ppt { container-type:inline-size!important; }
#salesDashboardDocument .gov-title { font-size:clamp(6px,2.35cqw,24px)!important; }
#salesDashboardDocument .sales-ppt-title { font-size:clamp(10px,4.1cqw,42px)!important; }
#salesDashboardDocument .sales-ppt-title span { border-bottom-width:clamp(2px,.78cqw,8px)!important; }
#salesDashboardDocument.sales-ppt .sales-ppt-footer .contact { font-size:clamp(5px,2.15cqw,22px)!important; }
#salesDashboardDocument.sales-ppt .sales-ppt-footer .social { font-size:clamp(5px,2.05cqw,21px)!important; }
/* Parent width, rather than the device width, controls iframe layouts. */
.dashboard,.dashboard .topbar,.dashboard .season,.pre-report,.pre-paper,.pre-scroll,.sales-actions { min-width:0!important;box-sizing:border-box!important; }
.dashboard .topbar { max-width:100%!important; }
.dashboard .season { max-width:100%!important; }
.pre-report .pre-paper { max-width:100%!important; }
.pre-report .pre-scroll { max-width:100%!important;overflow-x:auto!important;-webkit-overflow-scrolling:touch!important; }
@media(max-width:900px){
 .dashboard .topbar{display:flex!important;flex-direction:column!important;align-items:stretch!important;gap:8px!important}
 .dashboard .topbar .title{width:100%!important}
 .dashboard .topbar form.season{width:100%!important;display:grid!important;grid-template-columns:minmax(0,auto) minmax(0,1fr)!important;align-items:center!important;gap:7px 9px!important;flex:none!important}
 .dashboard .topbar form.season select{min-width:0!important;width:100%!important;max-width:100%!important}
 .sales-actions,.pre-export-bar{max-width:100%!important;flex-wrap:wrap!important}
}
@media(max-width:480px){
 .dashboard .topbar{padding:10px 8px!important}
 .dashboard .topbar form.season{grid-template-columns:minmax(0,1fr)!important}
 .dashboard .topbar form.season label{white-space:normal!important}
 .dashboard .topbar form.season select{min-height:36px!important}
 .pre-report .pre-paper{padding:12px 9px!important}
}
</style>
<script>
(function(){
const paper=document.getElementById('salesDashboardDocument');if(!paper)return;
const body=paper.querySelector('.sales-ppt-body');
const guide=document.getElementById('salesDashboardGuide'),guideToggle=document.getElementById('salesGuideToggle');
if(guide&&guideToggle){guideToggle.addEventListener('click',()=>{const show=guide.hidden;guide.hidden=!show;guideToggle.textContent=window.salesDashboardLanguage==='sw'?(show?'Ficha Mwongozo':'Onyesha Mwongozo'):(show?'Hide Guide':'Show Guide');guideToggle.setAttribute('aria-expanded',String(show));});}

/* The poster background is embedded in the CSS. Decode it before showing data.
   This also guards against a damaged/missing background after deployment. */
let backgroundReadyResolve;
const backgroundReady=new Promise(resolve=>{backgroundReadyResolve=resolve;});
function backgroundDone(ok){
 if(ok){paper.classList.add('sales-background-ready');paper.classList.remove('sales-background-failed');}
 else{paper.classList.add('sales-background-failed');paper.classList.remove('sales-background-ready');}
 backgroundReadyResolve(ok);
}
function checkSalesBackground(){
 const background=getComputedStyle(paper).backgroundImage;
 const match=background.match(/url\(["']?(.+?)["']?\)/);
 if(!match){backgroundDone(false);return;}
 const image=new Image();
 image.onload=()=>{if(image.naturalWidth>0 && image.naturalHeight>0){requestAnimationFrame(()=>{fit();backgroundDone(true);});}else backgroundDone(false);};
 image.onerror=()=>backgroundDone(false);
 image.src=match[1];
 if(image.complete && image.naturalWidth>0){requestAnimationFrame(()=>{fit();backgroundDone(true);});}
}
function fit(){if(!body)return;const width=paper.getBoundingClientRect().width||1023;const height=width*1447/1023;const areaHeight=height*.424;body.style.transform='none';const natural=body.scrollHeight||1;const availableWidth=width*.89;const scaleX=Math.min(1,availableWidth/(body.offsetWidth||availableWidth));const scaleY=Math.min(scaleX,areaHeight/natural);body.style.transform='scale('+Math.max(.01,scaleX)+','+Math.max(.01,scaleY)+')';}
window.salesDashboardFit=fit;window.addEventListener('resize',fit,{passive:true});window.addEventListener('message',function(event){if(event.source!==window.parent)return;if(event.data&&event.data.type==='tcb:layout-resize')requestAnimationFrame(fit);});if(window.ResizeObserver){const ro=new ResizeObserver(()=>requestAnimationFrame(fit));ro.observe(paper);if(paper.parentElement)ro.observe(paper.parentElement);}document.fonts?.ready.then(fit);requestAnimationFrame(fit);checkSalesBackground();
const button=document.getElementById('salesExportButton'),menu=document.getElementById('salesExportOptions'),progress=document.getElementById('salesProgress'),status=document.getElementById('salesProgressText'),bar=document.getElementById('salesProgressFill'),percent=document.getElementById('salesProgressPercent');
if(!button||!menu)return;
button.addEventListener('click',e=>{e.stopPropagation();menu.hidden=!menu.hidden;button.setAttribute('aria-expanded',String(!menu.hidden));});document.addEventListener('click',e=>{if(!e.target.closest('.sales-export-control')){menu.hidden=true;button.setAttribute('aria-expanded','false');}});
function update(n,msg){if(progress)progress.hidden=false;if(bar)bar.style.width=n+'%';if(percent)percent.textContent=n+'%';if(status)status.textContent=msg;if(window.reportTask)window.reportTask.update(n,msg);}
function save(blob,name){const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(u);a.remove()},5000);}
function base(){return (window.salesDashboardLanguage==='sw'?'TCB_Dashibodi_Mauzo_':'TCB_Sales_Dashboard_')+String(<?=json_encode($season)?>).replace(/\W/g,'_')+'_Friday_'+<?=json_encode($salesReportDate)?>;}
async function library(url,check){if(check())return;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=url;s.onload=resolve;s.onerror=()=>reject(new Error('Could not load export library: '+url));document.head.appendChild(s);});if(!check())throw new Error('Export library unavailable');}
async function snapshot(){
 if(!(await backgroundReady))throw new Error('Sales report background is unavailable. Export was stopped to prevent an incomplete report.');
 await library('https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js',()=>!!window.html2canvas);
 if(document.fonts?.ready)await document.fonts.ready;
 update(40,'Rendering full-resolution A4 dashboard…');
 const canvas=await html2canvas(paper,{
  scale:2.5,useCORS:true,allowTaint:false,backgroundColor:'#ffffff',logging:false,
  width:1023,height:1447,windowWidth:1200,windowHeight:1600,scrollX:0,scrollY:0,
  onclone:doc=>{
   const p=doc.getElementById('salesDashboardDocument');
   // Move the page out of responsive dashboard wrappers, which otherwise clip the PDF.
   doc.body.appendChild(p);
   p.style.setProperty('position','absolute','important');
   p.style.setProperty('top','0','important');
   p.style.setProperty('left','0','important');
   p.style.setProperty('width','1023px','important');
   p.style.setProperty('min-width','1023px','important');
   p.style.setProperty('max-width','1023px','important');
   p.style.setProperty('height','1447px','important');
   p.style.setProperty('aspect-ratio','auto','important');
   p.style.setProperty('margin','0','important');
   p.style.setProperty('box-shadow','none','important');
   p.style.setProperty('overflow','hidden','important');
   const b=p.querySelector('.sales-ppt-body');
   if(b){
    b.style.setProperty('width','993px','important');
    b.style.setProperty('left','15px','important');
    b.style.setProperty('top','21.6%','important');
    b.style.setProperty('transform','none','important');
    const natural=b.scrollHeight||1;
    const scaleX=993/(b.offsetWidth||993);
    const scaleY=Math.min(scaleX,1447*.424/natural);
    b.style.setProperty('transform','scale('+scaleX+','+scaleY+')','important');
   }
  }
 });
 if(canvas.width<2000||canvas.height<3000)throw new Error('Export image dimensions are unexpectedly small');
 if(guide&&!guide.hidden){
  update(53,'Rendering dashboard guide…');
  const guideCanvas=await html2canvas(guide,{scale:2.5,useCORS:true,backgroundColor:'#ffffff',logging:false,width:1023,height:1447,windowWidth:1200,windowHeight:1600,scrollX:0,scrollY:0,
   onclone:doc=>{const g=doc.getElementById('salesDashboardGuide');doc.body.appendChild(g);g.hidden=false;g.style.setProperty('position','absolute','important');g.style.setProperty('top','0','important');g.style.setProperty('left','0','important');g.style.setProperty('width','1023px','important');g.style.setProperty('max-width','1023px','important');g.style.setProperty('height','1447px','important');g.style.setProperty('aspect-ratio','auto','important');g.style.setProperty('margin','0','important');g.style.setProperty('box-shadow','none','important');}});
  const combined=document.createElement('canvas');combined.width=canvas.width;combined.height=canvas.height+guideCanvas.height;
  const ctx=combined.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,combined.width,combined.height);ctx.drawImage(canvas,0,0);ctx.drawImage(guideCanvas,0,canvas.height);
  return combined;
 }
 return canvas;
}
function canvasBlob(canvas,type,quality){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Image encoding failed')),type,quality));}
function xmlEscape(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
async function excelWithImage(canvas){
 await library('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js',()=>!!window.XLSX);
 await library('https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js',()=>!!window.JSZip);
 update(65,'Creating Excel workbook with embedded dashboard image…');
 const wb=XLSX.utils.book_new();
 const ws=XLSX.utils.aoa_to_sheet([['TANZANIA COFFEE BOARD — SALES DASHBOARD'],['Dashboard image is embedded below. Editable source tables are in the following sheets.']]);
 ws['!cols']=[{wch:100}];XLSX.utils.book_append_sheet(wb,ws,'Dashboard');
 paper.querySelectorAll('table').forEach((t,i)=>XLSX.utils.book_append_sheet(wb,XLSX.utils.table_to_sheet(t,{raw:true}),'Data '+(i+1)));if(guide&&!guide.hidden){const guideRows=[[guide.querySelector('h2')?.textContent||'GUIDE TO UNDERSTANDING THE COFFEE SALES DASHBOARD']];guide.querySelectorAll('h3,h4,p').forEach(el=>guideRows.push([el.textContent.trim()]));const gws=XLSX.utils.aoa_to_sheet(guideRows);gws['!cols']=[{wch:110}];XLSX.utils.book_append_sheet(wb,gws,'Guide');}
 const bytes=XLSX.write(wb,{bookType:'xlsx',type:'array'});
 const zip=await JSZip.loadAsync(bytes);
 const image=await canvasBlob(canvas,'image/png');zip.file('xl/media/dashboard.png',image);
 const sheet='xl/worksheets/sheet1.xml';let sheetXml=await zip.file(sheet).async('string');
 sheetXml=sheetXml.replace('</worksheet>','<drawing r:id="rIdDashboard" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"/></worksheet>');zip.file(sheet,sheetXml);
 const relPath='xl/worksheets/_rels/sheet1.xml.rels';let rel=zip.file(relPath)?await zip.file(relPath).async('string'):'<'+'?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"></Relationships>';
 rel=rel.replace('</Relationships>','<Relationship Id="rIdDashboard" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing" Target="../drawings/drawing1.xml"/></Relationships>');zip.file(relPath,rel);
 const cx=1023*9525,cy=Math.round(1023*canvas.height/canvas.width)*9525;
 zip.file('xl/drawings/drawing1.xml','<'+'?xml version="1.0" encoding="UTF-8" standalone="yes"?><xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><xdr:oneCellAnchor><xdr:from><xdr:col>0</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>3</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:from><xdr:ext cx="'+cx+'" cy="'+cy+'"/><xdr:pic><xdr:nvPicPr><xdr:cNvPr id="1" name="Sales Dashboard"/><xdr:cNvPicPr/></xdr:nvPicPr><xdr:blipFill><a:blip xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" r:embed="rIdImage1"/><a:stretch><a:fillRect/></a:stretch></xdr:blipFill><xdr:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="'+cx+'" cy="'+cy+'"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></xdr:spPr></xdr:pic><xdr:clientData/></xdr:oneCellAnchor></xdr:wsDr>');
 zip.file('xl/drawings/_rels/drawing1.xml.rels','<'+'?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rIdImage1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="../media/dashboard.png"/></Relationships>');
 let ct=await zip.file('[Content_Types].xml').async('string');
 if(!ct.includes('Extension="png"'))ct=ct.replace('</Types>','<Default Extension="png" ContentType="image/png"/></Types>');
 ct=ct.replace('</Types>','<Override PartName="/xl/drawings/drawing1.xml" ContentType="application/vnd.openxmlformats-officedocument.drawing+xml"/></Types>');zip.file('[Content_Types].xml',ct);
 save(await zip.generateAsync({type:'blob',compression:'DEFLATE'}),base()+'.xlsx');
}
async function wordWithImage(canvas){
 await library('https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js',()=>!!window.JSZip);
 update(75,'Creating a genuine Word DOCX document…');
 const hasGuide=canvas.height>canvas.width*1.7;
 const pageHeight=hasGuide?Math.round(canvas.height/2):canvas.height;
 const first=document.createElement('canvas');first.width=canvas.width;first.height=pageHeight;first.getContext('2d').drawImage(canvas,0,0,canvas.width,pageHeight,0,0,canvas.width,pageHeight);
 const png=await canvasBlob(first,'image/png');
 let secondPng=null;if(hasGuide){const second=document.createElement('canvas');second.width=canvas.width;second.height=pageHeight;second.getContext('2d').drawImage(canvas,0,pageHeight,canvas.width,pageHeight,0,0,canvas.width,pageHeight);secondPng=await canvasBlob(second,'image/png');}
 const zip=new JSZip();
 const cx=5486400,cy=Math.round(cx*1447/1023);
 const xml='<'+'?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
 zip.file('[Content_Types].xml',xml+'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>');
 zip.file('_rels/.rels',xml+'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>');
 zip.file('word/_rels/document.xml.rels',xml+'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rIdImage1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/dashboard.png"/></Relationships>');
 zip.file('word/media/dashboard.png',png);if(secondPng)zip.file('word/media/guide.png',secondPng);
 const drawing='<w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="'+cx+'" cy="'+cy+'"/><wp:docPr id="1" name="Tanzania Coffee Board Sales Dashboard"/><a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:nvPicPr><pic:cNvPr id="0" name="Dashboard"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" r:embed="rIdImage1"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="'+cx+'" cy="'+cy+'"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing>';
 const wordDocumentXml=xml+'<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><w:body><w:p><w:pPr><w:jc w:val="center"/><w:spacing w:before="0" w:after="0"/></w:pPr><w:r>'+drawing+'</w:r></w:p><w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="180" w:right="180" w:bottom="180" w:left="180" w:header="0" w:footer="0" w:gutter="0"/></w:sectPr></w:body></w:document>';
 if(secondPng){
  const secondDrawing=drawing.replace(/rIdImage1/g,'rIdImage2').replace('id="1" name="Tanzania Coffee Board Sales Dashboard"','id="2" name="Coffee Sales Dashboard Guide"');
  const pageBreak='<w:p><w:r><w:br w:type="page"/></w:r></w:p>';
  const secondParagraph='<w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r>'+secondDrawing+'</w:r></w:p>';
  const updated=wordDocumentXml.replace('</w:body>',pageBreak+secondParagraph+'</w:body>');zip.file('word/document.xml',updated);
  const relName='word/_rels/document.xml.rels';const rel=await zip.file(relName).async('string');zip.file(relName,rel.replace('</Relationships>','<Relationship Id="rIdImage2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/guide.png"/></Relationships>'));
 }else zip.file('word/document.xml',wordDocumentXml);
 save(await zip.generateAsync({type:'blob',compression:'DEFLATE'}),base()+'.docx');
}
menu.addEventListener('click',async e=>{
 const type=e.target.closest('[data-type]')?.dataset.type;if(!type)return;
 e.stopPropagation();menu.hidden=true;button.disabled=true;const task=window.reportTask.start('Exporting Sales Dashboard','Preparing '+type.toUpperCase()+' export…');update(5,'Preparing dashboard export…');window.reportTask.update(5,'Preparing dashboard export…');
 try{
  const canvas=await snapshot();
  if(type==='png'||type==='jpg'){update(85,'Encoding image…');save(await canvasBlob(canvas,type==='png'?'image/png':'image/jpeg',.96),base()+'.'+type);}
  else if(type==='pdf'){
   await library('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js',()=>!!window.jspdf?.jsPDF);
   update(85,'Composing PDF…');const pdf=new jspdf.jsPDF({orientation:'portrait',unit:'mm',format:'a4',compress:true});const pageCount=Math.max(1,Math.round(canvas.height/(canvas.width*1447/1023)));for(let i=0;i<pageCount;i++){if(i)pdf.addPage();const part=document.createElement('canvas');part.width=canvas.width;part.height=Math.round(canvas.height/pageCount);part.getContext('2d').drawImage(canvas,0,i*part.height,canvas.width,part.height,0,0,part.width,part.height);pdf.addImage(part.toDataURL('image/png'),'PNG',0,0,210,297);}pdf.save(base()+'.pdf');
  }else if(type==='xlsx')await excelWithImage(canvas);
  else if(type==='doc')await wordWithImage(canvas);
  update(100,'Export completed');window.reportTask.end(task,false);
 }catch(err){update(0,'Export failed');window.reportTask.end(task,true);alert('Dashboard export failed: '+err.message);console.error(err);}
 finally{button.disabled=false;setTimeout(()=>{if(progress)progress.hidden=true;},2200);}
});
})();
</script>


<style id="sales-language-switch-style">.sales-language-switch{display:inline-flex;gap:2px;border:1px solid #b89a7b;border-radius:7px;padding:3px;background:#f4ede5}.sales-lang-btn{border:0;border-radius:5px;padding:7px 13px;background:transparent;color:#62442e;font-size:12px;font-weight:700;cursor:pointer}.sales-lang-btn.active{background:#6f4e37;color:white;box-shadow:0 1px 4px #0002}.sales-lang-btn:focus-visible{outline:2px solid #ae733b;outline-offset:2px}@media(max-width:520px){.sales-lang-btn{padding:6px 9px}}</style>
<script id="sales-language-toggle-js">(()=>{
const dict={"THE UNITED REPUBLIC OF TANZANIA":"JAMHURI YA MUUNGANO WA TANZANIA","MINISTRY OF AGRICULTURE":"WIZARA YA KILIMO","TANZANIA COFFEE BOARD":"BODI YA KAHAWA TANZANIA","SALES DASHBOARD":"DASHIBODI YA MAUZO YA KAHAWA","Sale Season (FY)":"Msimu wa Mauzo","End Date":"Tarehe ya Mwisho","Market Reference Prices":"Wastani wa Bei Sokoni","Market":"Soko","Coffee Type":"Aina ya Kahawa","Price":"Bei","Terminal (USD/kg)":"Soko la Kimataifa (Safi)(USD/kg)","Farmgate (TZS/kg)":"Soko la Awali (ghafi)(TZS/kg)","Clean Auction (USD/kg)":"Mnada wa Kahawa Safi (USD/kg)","Farmgate Market":"Soko la Kahawa Ghafi","Clean Coffee Market":"Soko la Kahawa Safi","This Week (MT)":"Wiki Hii (Tani)","Value (TZS)":"Thamani (TZS)","Value ($)":"Thamani (USD)","Season Total (MT)":"Jumla ya Msimu (Tani)","Total Value (TZS)":"Jumla ya Thamani (TZS)","Total Value ($)":"Jumla ya Thamani (USD)","Grand Total":"Jumla Kuu","Production":"Uzalishaji","Estimated Production (MT)":"Makadirio ya Uzalishaji (Tani)","Percentage Achieved":"Asilimia ya Mafanikio","1  Kagera Auction":"1  Mnada wa Kagera","2  Certified Coffee":"2  Kahawa Yenye Vyeti (Certified)","3  Farmgate Contracts":"3  Mikataba ya Kahawa Ghafi","Clean Auction":"Mnada wa Kahawa Safi","Direct Export":"Mauzo ya Moja kwa Moja Nje","Local Roast":"Ukaangaji wa Ndani","Local Sale":"Mauzo ya Ndani","Dry Cherry":"Kahawa Maganda","Clean Coffee (Ungraded)":"Kahawa Safi (Ungraded)","M-Arabica":"Arabika Laini","H-Arabica":"Arabika Ngumu","Robusta":"Robusta","Arabica":"Arabika","H/Arabica (Dry Cherry)":"Arabika Ngumu (Maganda)","Robusta (Dry Cherry)":"Robusta (Maganda)","THE UNITED REPUBLIC OF TANZANIA · TANZANIA COFFEE BOARD":"JAMHURI YA MUUNGANO WA TANZANIA · BODI YA KAHAWA TANZANIA","GUIDE TO UNDERSTANDING THE COFFEE SALES DASHBOARD":"MWONGOZO WA KUELEWA DASHIBODI YA MAUZO YA KAHAWA","The Tanzania Coffee Board Sales Dashboard summarizes the quantity, average reference prices and value of coffee sold through different marketing channels, showing weekly and seasonal sales performance.":"Dashibodi ya Mauzo ya Bodi ya Kahawa Tanzania inaonesha kiasi, bei elekezi za wastani na thamani ya kahawa iliyouzwa kupitia njia mbalimbali za masoko, kwa wiki na kwa msimu.","1. Reporting Period":"1. Kipindi cha Taarifa","2. Market Reference Prices":"2. Wastani wa Bei za Masoko","3. Farmgate Market":"3. Soko la Kahawa Ghafi","4. Clean Coffee Market":"4. Soko la Kahawa Safi","4. Types of Coffee":"5. Aina za Kahawa","6. Understanding the Sales Figures":"6. Maana ya Takwimu za Mauzo","Sales Season (FY – Financial Year):":"Msimu wa Mauzo (Mwaka wa Fedha):","Runs from 1 July to 30 June of the following year.":"Huanzia tarehe 1 Julai hadi tarehe 30 Juni ya mwaka unaofuata.","End Date (Reporting Date):":"Tarehe ya Mwisho (Tarehe ya Taarifa):","The selected Friday on which the sales report ends.":"Tarehe ya siku ya Ijumaa ya kila wiki, inayochaguliwa kuwa tarehe ya mwisho ya taarifa ya mauzo.","This Week:":"Wiki Hii:","Sales recorded from Monday to Friday of the reporting week.":"Mauzo yaliyorekodiwa kuanzia Jumatatu hadi Ijumaa ya wiki ya taarifa.","Season Total:":"Jumla ya Msimu:","Cumulative sales recorded from 1 July to the selected reporting Friday.":"Jumla ya mauzo kuanzia tarehe 1 Julai hadi Ijumaa iliyochaguliwa.","These are reference prices for the selected reporting Friday date:":"Hizi ni wastani wa bei kwa tarehe ya Ijumaa iliyochaguliwa:","Terminal (USD/kg):":"Soko la Kimataifa (USD/kg):","World coffee reference prices for Arabica (New York market) and Robusta (London market).":"Wastani wa bei za kahawa duniani kwa Arabika (soko la New York) na Robusta (soko la London).","Farmgate (TZS/kg):":"Soko la Awali (TZS/kg):","Reference prices per kilogram for Hard Arabica Dry Cherry, Robusta Dry Cherry, Arabica CPU, and Arabica HP.":"Wastani wa bei kwa kilo kwa Arabika Ngumu ya Maganda, Robusta ya Maganda, Arabika Laini (CPU) na Arabika Laini (HP).","Clean Auction (USD/kg):":"Mnada wa Kahawa Safi (USD/kg):","Reference prices per kilogram for graded Arabica and Robusta coffee sold through the clean coffee auction.":"Wastani wa bei kwa kilo kwa kahawa safi ya Arabika na Robusta iliyopangwa madaraja (Graded) na kuuzwa mnadani.","This covers coffee traded at the primary marketing stage through three categories:":"Hii inahusisha kahawa inayouzwa katika hatua ya awali ya masoko kupitia makundi matatu:","Kagera Auction:":"Mnada wa Kagera:","Coffee sold through the Kagera Coffee Auction, including Dry Coffee Cherries (naturally dried coffee) and Clean Coffee (home-hulled, ungraded coffee).":"Kahawa ghafi inayouzwa katika Mnada wa Kagera, ikijumuisha kahawa ya maganda iliyokaushwa kwa njia ya asili na kahawa safi iliyokobolewa majumbani bila kupangwa madaraja (Ungraded).","Certified Coffee:":"Kahawa Yenye Vyeti (Certified):","Coffee produced and marketed under recognized certification standards.":"Kahawa inayozalishwa na kuuzwa kwa kuzingatia viwango vinavyotambuliwa na matakwa ya cheti husika.","Farmgate Contracts:":"Mikataba ya Kahawa Ghafi (Farmgate Contracts):","Mild (washed) coffee or dry cherry coffee sold through farmgate coffee contracts registered with the Tanzania Coffee Board.":"Kahawa laini au maganda, inayouzwa kupitia Mikataba ya Kahawa Ghafi iliyosajiliwa na Bodi.","These covers processed and graded coffee traded through four marketing channels:":"Hii inahusisha kahawa iliyokobolewa na kupangwa madaraja, inayouzwa kupitia njia nne za masoko:","Clean Auction:":"Mnada wa Kahawa Safi:","Graded clean coffee sold through a competitive auction system to licensed green coffee exporters and local coffee roasters. The purchased coffee is subsequently exported or roasted locally.":"Kahawa safi iliyopangwa madaraja na kuuzwa kwa ushindani mnadani kwa wanunuzi wenye leseni ya kusafirisha kahawa nje ya nchi (Exporter) au wakaangaji wa ndani. Kahawa hiyo baadaye husafirishwa nje au kukaangwa nchini.","Direct Export:":"Mauzo ya Moja kwa Moja Nje:","Coffee sold directly to international buyers as a final sales channel.":"Kahawa inayouzwa moja kwa moja kwa wanunuzi wa kimataifa kama njia ya mwisho ya mauzo.","Local Roast:":"Ukaangaji wa Ndani:","Coffee sold to local roasting businesses as a final sales channel.":"Kahawa inayouzwa kwa wanunuzi wenye leseni za ukaangaji wa kahawa nchini kama njia ya mwisho ya mauzo.","Local Sale:":"Mauzo ya Ndani (Local Sale):","An intermediate sales channel for graded clean coffee traded between local buyers before reaching final markets, such as Direct Export or Local Roast. The dashboard reports the remaining Local Sale balance after deducting quantities subsequently sold through Direct Export or Local Roast.":"Ni njia ya kati ya mauzo ya kahawa safi iliyopangwa katika madaraja, ambapo wafanyabiashara wa ndani hununua na kuuziana kahawa wao kwa wao kabla ya kahawa hiyo kuuzwa kupitia masoko ya mwisho, kama vile mauzo ya moja kwa moja nje ya nchi au ukaangaji wa ndani. Dashibodi inaonesha salio la mauzo ya ndani baada ya kutoa kiasi cha kahawa kilichouzwa kupitia masoko hayo ya mwisho.","Mild Arabica (M-Arabica):":"Arabika Laini (M-Arabica):","Arabica coffee processed using the wet method, where harvested ripe cherries are pulped before drying.":"Kahawa ya Arabika iliyochakatwa kwa njia ya maji (Washed process), ambapo matunda yaliyoiva huondolewa maganda na kusindikwa kabla ya kukaushwa na kukobolewa.","Hard Arabica (H-Arabica):":"Arabika Ngumu (H-Arabica):","Arabica coffee processed using the natural method, where whole ripe cherries are dried into dry cherries before hulling.":"Kahawa ya Arabika iliyochakatwa kwa njia ya asili, ambapo matunda yaliyoiva hukaushwa yakiwa na maganda kabla ya kukobolewa.","Robusta:":"Robusta:","Robusta coffee, which in Tanzania is predominantly processed naturally by drying whole ripe cherries before hulling.":"Kahawa ya Robusta, ambayo nchini Tanzania kwa sehemu kubwa huchakatwa kwa njia ya asili kwa kukausha matunda yaliyoiva kabla ya kukobolewa.","MT (Metric Tonne): 1 MT = 1,000 kilograms.":"Tani 1 (MT) = kilo 1,000.","Indicator":"Kiashiria","Meaning":"Maana","Value (TZS/USD)":"Thamani (TZS/USD)","Total Value (TZS/USD)":"Jumla ya Thamani (TZS/USD)","Quantity sold during the reporting week (Monday–Friday).":"Kiasi kilichouzwa katika wiki ya taarifa (Jumatatu–Ijumaa).","Monetary value of coffee sold during the reporting week.":"Thamani ya fedha ya kahawa iliyouzwa katika wiki ya taarifa.","Cumulative quantity sold from 1 July to the reporting Friday.":"Jumla ya kiasi kilichouzwa kuanzia tarehe 1 Julai hadi Ijumaa ya taarifa.","Cumulative sales value from 1 July to the reporting Friday.":"Jumla ya thamani ya mauzo kuanzia tarehe 1 Julai hadi Ijumaa ya taarifa.","Combined clean coffee sales across all channels, including the remaining Local Sale balance.":"Jumla ya mauzo ya kahawa safi katika njia zote, ikijumuisha salio la mauzo ya ndani.","Expected national clean coffee production for the season.":"Makadirio ya uzalishaji wa kahawa safi nchini kwa msimu.","Total clean coffee sold as a percentage of estimated national production.":"Asilimia ya kahawa safi iliyouzwa ikilinganishwa na makadirio ya uzalishaji nchini.","3 Farmgate Contracts":"3 Mikataba ya Kahawa Ghafi","Farmgate Contracts":"Mikataba ya Kahawa Ghafi","Arabica (NY)":"Arabika (NY)","Arabica CPU":"Arabika Laini (CPU)","Arabica HP":"Arabika Laini (HP)","Sales Season":"Msimu wa Mauzo","Reporting Friday":"Ijumaa ya Taarifa","1 MT = 1,000 kilograms.":"Tani 1 (MT) = kilo 1,000.","1 MT = 1,000 kg.":"Tani 1 (MT) = kilo 1,000.","TANZANIA COFFEE BOARD · www.coffee.go.tz":"BODI YA KAHAWA TANZANIA · www.coffee.go.tz","5. Types of Coffee":"5. Aina za Kahawa"};
const targets=[document.getElementById('salesDashboardDocument'),document.getElementById('salesDashboardGuide')].filter(Boolean);
const entries=[];
for(const root of targets){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(!node.nodeValue.trim()||node.parentElement?.closest('script,style'))continue;entries.push([node,node.nodeValue]);}}
const english=document.getElementById('salesLangEnglish'),swahili=document.getElementById('salesLangSwahili');if(!english||!swahili)return;
const translate=(value)=>{const trimmed=value.trim();let out=dict[trimmed];if(!out){const bullet=trimmed.match(/^([•\u2022]\s*)(.+)$/);if(bullet&&dict[bullet[2]])out=bullet[1]+dict[bullet[2]];}if(!out){const match=trimmed.match(/^(\d+)\s+(.+)$/);if(match&&dict[match[2]])out=match[1]+' '+dict[match[2]];}
if(!out&&trimmed.startsWith('Sales Season '))out='Msimu wa Mauzo '+trimmed.slice(13).replace(' · Reporting Friday ',' · Ijumaa ya Taarifa ');
if(!out&&trimmed.startsWith('· Reporting Friday '))out='· Ijumaa ya Taarifa '+trimmed.slice('· Reporting Friday '.length);
return out?value.replace(trimmed,out):value;};
function setLanguage(lang){const sw=lang==='sw';for(const [node,original] of entries){if(node.isConnected)node.nodeValue=sw?translate(original):original;}
english.classList.toggle('active',!sw);swahili.classList.toggle('active',sw);english.setAttribute('aria-pressed',String(!sw));swahili.setAttribute('aria-pressed',String(sw));
document.documentElement.lang=sw?'sw':'en';document.getElementById('salesGuideToggle').textContent=sw?(document.getElementById('salesDashboardGuide').hidden?'Onyesha Mwongozo':'Ficha Mwongozo'):(document.getElementById('salesDashboardGuide').hidden?'Show Guide':'Hide Guide');
document.getElementById('salesExportButton').textContent=sw?'⇩ Hamisha Dashibodi':'⇩ Export Dashboard';
window.salesDashboardLanguage=lang;window.salesDashboardFit?.();}
english.addEventListener('click',()=>setLanguage('en'));swahili.addEventListener('click',()=>setLanguage('sw'));
window.salesDashboardApplyLanguage=setLanguage;
})();</script>
