<script id="market-friday-price-edit-js">
(()=>{
 const dialog=document.getElementById('marketPriceDialog'),form=document.getElementById('marketPriceForm');if(!dialog||!form)return;
 const input=document.getElementById('marketPriceInput'),error=document.getElementById('marketPriceError'),save=document.getElementById('marketPriceSave');
 const names={ny:'Arabica (NY)',london:'Robusta (London)',hard_cherry:'H/Arabica (Dry Cherry)',robusta_cherry:'Robusta (Dry Cherry)',cpu:'Arabica CPU',hp:'Arabica HP',auction_arabica:'Clean Auction Arabica',auction_robusta:'Clean Auction Robusta'};
 let cell=null,focus=null;
 const close=()=>{if(save.disabled)return;dialog.hidden=true;dialog.setAttribute('aria-hidden','true');focus?.focus();};
 const open=c=>{cell=c;focus=document.activeElement;document.getElementById('marketPriceHeading').textContent='Edit '+names[c.dataset.priceKey];document.getElementById('marketPriceUnit').textContent=['hard_cherry','robusta_cherry','cpu','hp'].includes(c.dataset.priceKey)?'(TZS/kg)':'(USD/kg)';input.value=c.dataset.price||'';error.textContent='';dialog.hidden=false;dialog.setAttribute('aria-hidden','false');input.focus();input.select();};
 document.querySelectorAll('#salesDashboardDocument .market-price-edit').forEach(c=>{c.addEventListener('dblclick',()=>open(c));c.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open(c);}});});
 document.getElementById('marketPriceCancel').addEventListener('click',close);dialog.addEventListener('click',e=>{if(e.target===dialog)close();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dialog.hidden)close();});
 form.addEventListener('submit',async e=>{e.preventDefault();if(save.disabled||!cell)return;const raw=input.value.trim();if(!/^\d{1,10}(?:\.\d{1,4})?$/.test(raw)){error.textContent='Enter a valid non-negative price (up to four decimal places).';return;}
  save.disabled=true;save.textContent='Saving…';error.textContent='';
  try{
   const body=new URLSearchParams({csrf:<?=json_encode($_SESSION['terminal_price_csrf'])?>,season:<?=json_encode($season)?>,report_date:<?=json_encode($salesReportDate)?>,price_key:cell.dataset.priceKey,price:raw});
   const response=await fetch('dashboard.php?action=save_market_friday_price',{method:'POST',body,credentials:'same-origin',headers:{Accept:'application/json'}});
   const result=await response.json();if(!response.ok||!result.success)throw new Error(result.message||'Unable to save price');
   const value=Number(result.price),dec=['hard_cherry','robusta_cherry','cpu','hp'].includes(cell.dataset.priceKey)?0:2;
   cell.dataset.price=String(value);cell.textContent=value.toLocaleString('en-US',{minimumFractionDigits:dec,maximumFractionDigits:dec});
   dialog.hidden=true;dialog.setAttribute('aria-hidden','true');focus?.focus();window.salesDashboardFit?.();
  }catch(err){error.textContent=err.message||'Unable to save price';}finally{save.disabled=false;save.textContent='Save Price';}
 });
})();
</script>
<div id="certifiedCoffeeDialog" class="terminal-price-dialog" hidden data-html2canvas-ignore="true" aria-hidden="true">
 <form id="certifiedCoffeeForm" class="terminal-price-card" role="dialog" aria-modal="true" aria-labelledby="certifiedCoffeeHeading">
  <h3 id="certifiedCoffeeHeading">Edit Certified Coffee</h3><p>Farmgate Market · selected Friday report. Quantities are in MT; values are in TZS.</p>
  <label for="certWeekMt">This Week (MT)</label><input id="certWeekMt" type="number" min="0" step="0.001" required>
  <label for="certWeekValue">Value (TZS)</label><input id="certWeekValue" type="number" min="0" step="0.01" required>
  <label for="certSeasonMt">Season Total (MT)</label><input id="certSeasonMt" type="number" min="0" step="0.001" required>
  <label for="certSeasonValue">Total Value (TZS)</label><input id="certSeasonValue" type="number" min="0" step="0.01" required>
  <div id="certifiedCoffeeError" class="error" role="alert"></div>
  <div class="actions"><button type="button" id="certifiedCoffeeCancel">Cancel</button><button type="submit" id="certifiedCoffeeSave">Save figures</button></div>
 </form>
</div>
<script id="certified-coffee-edit-js">
(()=>{
 const dialog=document.getElementById('certifiedCoffeeDialog'),form=document.getElementById('certifiedCoffeeForm');if(!dialog||!form)return;
 const fields={week_mt:document.getElementById('certWeekMt'),week_value_tzs:document.getElementById('certWeekValue'),season_mt:document.getElementById('certSeasonMt'),season_value_tzs:document.getElementById('certSeasonValue')};
 const cells=[...document.querySelectorAll('#salesDashboardDocument .certified-edit')],error=document.getElementById('certifiedCoffeeError'),save=document.getElementById('certifiedCoffeeSave');
 let previousFocus=null;
 const close=()=>{if(save.disabled)return;dialog.hidden=true;dialog.setAttribute('aria-hidden','true');previousFocus?.focus();};
 const open=()=>{previousFocus=document.activeElement;cells.forEach(c=>fields[c.dataset.field].value=c.dataset.value||'0');error.textContent='';dialog.hidden=false;dialog.setAttribute('aria-hidden','false');fields.week_mt.focus();};
 cells.forEach(c=>{c.addEventListener('dblclick',open);c.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}});});
 document.getElementById('certifiedCoffeeCancel').addEventListener('click',close);
 dialog.addEventListener('click',e=>{if(e.target===dialog)close();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dialog.hidden)close();});
 const fmt=(v,dec)=>Number(v).toLocaleString('en-US',{minimumFractionDigits:0,maximumFractionDigits:dec});
 form.addEventListener('submit',async e=>{e.preventDefault();if(save.disabled)return;const values={};
  for(const [k,input] of Object.entries(fields)){const raw=input.value.trim(),dec=k.endsWith('_mt')?3:2;if(!new RegExp('^\\d{1,14}(?:\\.\\d{1,'+dec+'})?$').test(raw)){error.textContent='Enter valid non-negative numbers (up to '+dec+' decimal places).';input.focus();return;}values[k]=raw;}
  save.disabled=true;save.textContent='Saving…';error.textContent='';
  try{
   const body=new URLSearchParams({...values,csrf:<?=json_encode($_SESSION['terminal_price_csrf'])?>,season:<?=json_encode($season)?>,report_date:<?=json_encode($salesReportDate)?>});
   const response=await fetch('dashboard.php?action=save_certified_coffee',{method:'POST',body,credentials:'same-origin',headers:{Accept:'application/json'}});
   const result=await response.json();if(!response.ok||!result.success)throw new Error(result.message||'Saving failed');
   cells.forEach(c=>{const k=c.dataset.field,v=Number(result.values[k]);c.dataset.value=String(v);c.textContent=v?fmt(v,k.endsWith('_mt')?3:2):'—';});
   const base=<?=json_encode([$farmWeekKg/1000-$certifiedCoffee['week_mt'],$farmWeekVal-$certifiedCoffee['week_value_tzs'],$farmSeasonKg/1000-$certifiedCoffee['season_mt'],$farmSeasonVal-$certifiedCoffee['season_value_tzs']])?>;
   const row=document.getElementById('farmgateGrandTotal');if(row){const keys=['week_mt','week_value_tzs','season_mt','season_value_tzs'];keys.forEach((k,i)=>{row.cells[i+1].textContent=fmt(Number(base[i])+Number(result.values[k]),i%2===0?3:2);});}
   save.disabled=false;dialog.hidden=true;dialog.setAttribute('aria-hidden','true');previousFocus?.focus();window.salesDashboardFit?.();
  }catch(err){error.textContent=err.message||'Unable to save figures';}finally{save.disabled=false;save.textContent='Save figures';}
 });
})();
</script>
<script id="report-sticky-toolbar-height">
(function(){
 const root=document.querySelector('body.report-sticky-mode .dashboard');
 if(!root)return;
 const toolbar=root.querySelector(':scope > .topbar');
 const exportBar=root.querySelector(':scope > .sales-actions, :scope > .pre-export-bar');
 if(!toolbar||!exportBar)return;
 const update=()=>{
   const toolbarHeight=Math.ceil(toolbar.getBoundingClientRect().height);
   const exportHeight=Math.ceil(exportBar.getBoundingClientRect().height);
   document.documentElement.style.setProperty('--report-toolbar-height',toolbarHeight+'px');
   document.documentElement.style.setProperty('--report-fixed-controls-height',(toolbarHeight+exportHeight+12)+'px');
 };
 update();
 window.addEventListener('resize',update,{passive:true});
 if(window.ResizeObserver){const observer=new ResizeObserver(update);observer.observe(toolbar);observer.observe(exportBar);}
})();
</script>
<style>
/* Shared report task indicator; independent of printable report content. */
#reportTaskOverlay[hidden]{display:none!important}
#reportTaskOverlay{position:fixed;inset:auto 18px 18px auto;z-index:2147483000;background:transparent;display:block;pointer-events:none;max-width:calc(100vw - 36px)}
.report-task-card{width:min(340px,100%);background:#fff;border-radius:17px;padding:25px;box-shadow:0 22px 75px rgba(0,0,0,.28);font-family:Arial,sans-serif;color:#3e2723;box-sizing:border-box}
.report-task-icon{width:46px;height:46px;border-radius:14px;background:#f2e7dc;color:#65452f;display:grid;place-items:center;font-size:23px;margin-bottom:13px}
.report-task-heading{font-size:18px;font-weight:800;margin:0 0 7px}
.report-task-description{font-size:13px;color:#685b51;line-height:1.5;min-height:20px;margin-bottom:18px}
.report-task-meter{height:9px;background:#eae4df;border-radius:20px;overflow:hidden}
#reportTaskBar{height:100%;width:0;background:linear-gradient(90deg,#795548,#ba8b52);border-radius:20px;transition:width .25s ease}
.report-task-bottom{display:flex;justify-content:space-between;margin-top:10px;font-size:12px;font-weight:700;color:#795548}
@media(prefers-reduced-motion:reduce){#reportTaskBar{transition:none}}
</style>
<div id="reportTaskOverlay" hidden role="status" aria-live="polite" aria-atomic="true" data-html2canvas-ignore="true">
 <div class="report-task-card"><div class="report-task-icon" aria-hidden="true">☕</div>
 <div class="report-task-heading" id="reportTaskHeading">Preparing report</div>
 <div class="report-task-description" id="reportTaskDescription">Please wait…</div>
 <div class="report-task-meter" role="progressbar" aria-label="Report task progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" id="reportTaskMeter"><div id="reportTaskBar"></div></div>
 <div class="report-task-bottom"><span id="reportTaskStage">Preparing</span><span id="reportTaskPercent">0%</span></div></div>
</div>
<script>
window.reportTask=(function(){
 let token=0,active=false;
 const el=id=>document.getElementById(id);
 function update(p,message){if(!active)return;const n=Math.max(0,Math.min(100,Math.round(p)));el('reportTaskBar').style.width=n+'%';el('reportTaskPercent').textContent=n+'%';el('reportTaskMeter').setAttribute('aria-valuenow',n);if(message)el('reportTaskDescription').textContent=message;el('reportTaskStage').textContent=n===100?'Completed':n>=80?'Finalizing':n>=30?'Processing':'Preparing';}
 function start(title,message){const id=++token;active=true;el('reportTaskHeading').textContent=title;el('reportTaskOverlay').hidden=false;update(0,message||'Preparing…');return id;}
 function end(id,failed){if(id!==token)return;if(!failed)update(100,'Your file is ready.');else{el('reportTaskStage').textContent='Failed';el('reportTaskDescription').textContent='The operation could not be completed.';}setTimeout(()=>{if(id===token){active=false;el('reportTaskOverlay').hidden=true;}},failed?1700:650);}
 window.addEventListener('pageshow',()=>{active=false;el('reportTaskOverlay').hidden=true;});
 return {start,update,end};
})();
(function(){
 const form=document.querySelector('body.report-sticky-mode form.season');
 /* Report navigation remains unblocked; no viewport loading overlay. */
 
})();
</script>

<style id="sales-dashboard-centered-columns">
/* Center the five-column market and sales tables in preview and export clones. */
#salesDashboardDocument .sales-table tr.market-reference-columns > th,
#salesDashboardDocument .sales-table tr.sales-column-heading > th {
  font-weight:800!important;
  text-align:center!important;
  vertical-align:middle!important;
}
#salesDashboardDocument .sales-table tr:not(.sales-band):not(.sales-section) > td,
#salesDashboardDocument .sales-table tr:not(.sales-band):not(.sales-section) > th {
  text-align:center!important;
  vertical-align:middle!important;
}
#salesDashboardDocument .sales-table tr:not(.sales-band):not(.sales-section) > td.sales-label,
#salesDashboardDocument .sales-table tr:not(.sales-band):not(.sales-section) > td.sales-num {
  text-align:center!important;
}
</style>
</body>
</html>
